{
  "name": "The Brighter Side",
  "description": "An application that helps you find the positive perspective on your daily problems by reframing them with an optimistic viewpoint, now with Live Voice support.",
  "requestFramePermissions": [
    "microphone"
  ]
}

import { GoogleGenAI } from "@google/genai";

export const getGeminiService = () => {
  if (!process.env.API_KEY) {
    throw new Error("API_KEY is not set in environment variables.");
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const OPTIMIST_INSTRUCTION = `You are 'The Optimist', an AI with a perpetually positive and encouraging perspective. Your sole purpose is to help people see the good in their problems. You are empathetic, wise, and always find a silver lining, a lesson to be learned, or an opportunity for growth. Respond directly to the user's problem with your optimistic reframing. Keep your responses encouraging and uplifting. If in a live conversation, be warm and supportive in your tone.`;

export const getBrighterSide = async (problem: string): Promise<string> => {
  try {
    const ai = getGeminiService();
    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Here is my problem: "${problem}". Please help me see the brighter side of this.`,
        config: {
            systemInstruction: OPTIMIST_INSTRUCTION,
            temperature: 0.8,
            topP: 0.9,
        }
    });

    return response.text || "I couldn't find the words, but I know there's a silver lining out there.";
  } catch (error) {
    console.error("Error generating content:", error);
    if (error instanceof Error) {
      return `An error occurred while trying to find the brighter side: ${error.message}. Please try again.`;
    }
    return "An unknown error occurred. Please try again.";
  }
};

import React, { useEffect, useRef, useState } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage } from '@google/genai';
import { OPTIMIST_INSTRUCTION, getGeminiService } from '../services/geminiService';
import { SunIcon } from './icons';

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const LiveVoiceMode: React.FC<{ onClose: () => void }> = ({ onClose }) => {
  const [isActive, setIsActive] = useState(false);
  const [userSpeech, setUserSpeech] = useState('');
  const [aiSpeech, setAiSpeech] = useState('');
  const [isAiSpeaking, setIsAiSpeaking] = useState(false);

  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionRef = useRef<any>(null);

  useEffect(() => {
    startSession();
    return () => stopSession();
  }, []);

  const startSession = async () => {
    try {
      const ai = getGeminiService();
      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsActive(true);
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);

            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const l = inputData.length;
              const int16 = new Int16Array(l);
              for (let i = 0; i < l; i++) {
                int16[i] = inputData[i] * 32768;
              }
              const pcmBlob = {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };

              sessionPromise.then((session) => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };

            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.inputTranscription) {
              setUserSpeech(prev => prev + ' ' + message.serverContent?.inputTranscription?.text);
            }
            if (message.serverContent?.outputTranscription) {
              setAiSpeech(prev => prev + ' ' + message.serverContent?.outputTranscription?.text);
            }
            if (message.serverContent?.turnComplete) {
              setUserSpeech('');
              setAiSpeech('');
            }

            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              setIsAiSpeaking(true);
              const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsAiSpeaking(false);
              };
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }

            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => s.stop());
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setIsAiSpeaking(false);
            }
          },
          onerror: (e) => console.error("Live Error:", e),
          onclose: () => setIsActive(false),
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
          },
          systemInstruction: OPTIMIST_INSTRUCTION,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
        },
      });

      sessionRef.current = await sessionPromise;
    } catch (err) {
      console.error("Failed to start live session:", err);
    }
  };

  const stopSession = () => {
    if (sessionRef.current) {
      sessionRef.current.close();
    }
    inputAudioContextRef.current?.close();
    outputAudioContextRef.current?.close();
    sourcesRef.current.forEach(s => s.stop());
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-white/80 backdrop-blur-md transition-all duration-500">
      <div className="w-full max-w-xl p-8 flex flex-col items-center">
        <div className={`relative w-48 h-48 rounded-full flex items-center justify-center transition-all duration-500 ${isAiSpeaking ? 'scale-110 shadow-[0_0_50px_rgba(250,204,21,0.5)]' : 'scale-100 shadow-xl'}`}>
          <div className={`absolute inset-0 rounded-full bg-yellow-400 opacity-20 animate-ping ${isAiSpeaking ? 'block' : 'hidden'}`}></div>
          <div className="z-10 bg-yellow-100 text-yellow-600 rounded-full p-8">
            <SunIcon className={`w-20 h-20 ${isAiSpeaking ? 'animate-spin-slow' : ''}`} />
          </div>
        </div>

        <h2 className="mt-8 text-2xl font-bold text-gray-800 text-center">
          {isActive ? (isAiSpeaking ? 'The Optimist is speaking...' : 'I\'m listening to you...') : 'Connecting to the bright side...'}
        </h2>

        <div className="mt-6 w-full space-y-4">
          {userSpeech && (
            <div className="bg-blue-50 p-4 rounded-2xl rounded-br-none border border-blue-100 animate-fade-in self-end ml-12">
              <p className="text-blue-800 text-sm italic">You: {userSpeech}</p>
            </div>
          )}
          {aiSpeech && (
            <div className="bg-yellow-50 p-4 rounded-2xl rounded-bl-none border border-yellow-100 animate-fade-in self-start mr-12">
              <p className="text-yellow-900 font-medium">{aiSpeech}</p>
            </div>
          )}
        </div>

        <button
          onClick={onClose}
          className="mt-12 px-8 py-3 bg-red-500 text-white rounded-full font-semibold shadow-lg hover:bg-red-600 transition-all active:scale-95"
        >
          End Conversation
        </button>

        <p className="mt-4 text-gray-400 text-xs text-center">
          Speak naturally. Your optimist is here to listen and find the silver lining in real-time.
        </p>
      </div>
      <style>{`
        @keyframes spin-slow {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
        .animate-spin-slow {
          animation: spin-slow 8s linear infinite;
        }
      `}</style>
    </div>
  );
};

export default LiveVoiceMode;

import React, { useState, useCallback } from 'react';
import { getBrighterSide } from './services/geminiService';
import { Status } from './types';
import Header from './components/Header';
import ProblemInput from './components/ProblemInput';
import ResponseCard from './components/ResponseCard';
import LiveVoiceMode from './components/LiveVoiceMode';

function App() {
  const [problem, setProblem] = useState<string>('');
  const [response, setResponse] = useState<string>('');
  const [status, setStatus] = useState<Status>(Status.IDLE);

  const handleSubmit = useCallback(async () => {
    if (!problem.trim()) return;

    setStatus(Status.LOADING);
    setResponse('');

    const result = await getBrighterSide(problem);

    if(result.toLowerCase().includes('an error occurred')){
        setStatus(Status.ERROR);
    } else {
        setStatus(Status.SUCCESS);
    }
    setResponse(result);
  }, [problem]);

  const handleClear = () => {
    setProblem('');
    setResponse('');
    setStatus(Status.IDLE);
  };

  const handleProblemChange = (newProblem: string) => {
    setProblem(newProblem);
    if(status !== Status.IDLE && status !== Status.LOADING) {
      setStatus(Status.IDLE);
      setResponse('');
    }
  };

  const startVoiceMode = () => {
    setStatus(Status.VOICE_MODE);
  };

  const stopVoiceMode = () => {
    setStatus(Status.IDLE);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-yellow-50 to-blue-50 flex flex-col items-center p-4 sm:p-6 lg:p-8 font-sans transition-colors duration-1000">
      <div className="w-full max-w-4xl mx-auto flex flex-col items-center">
        <div className="mt-4 mb-8">
          <button
            onClick={startVoiceMode}
            className="flex items-center gap-2 px-6 py-2 bg-white border border-yellow-200 rounded-full shadow-sm hover:shadow-md text-yellow-700 font-medium transition-all transform hover:-translate-y-1"
          >
            <span className="relative flex h-3 w-3">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-yellow-400 opacity-75"></span>
              <span className="relative inline-flex rounded-full h-3 w-3 bg-yellow-500"></span>
            </span>
            Try Voice Conversation
          </button>
        </div>

        <Header />

        <main className="w-full mt-10 flex flex-col items-center">
          <ProblemInput 
            problem={problem}
            onProblemChange={handleProblemChange}
            onSubmit={handleSubmit}
            isLoading={status === Status.LOADING}
          />
          <ResponseCard 
            status={status}
            response={response}
            onClear={handleClear}
          />
        </main>
      </div>

      {status === Status.VOICE_MODE && (
        <LiveVoiceMode onClose={stopVoiceMode} />
      )}

       <footer className="text-center text-gray-400 text-sm mt-auto py-8">
        <p>Powered by Gemini Live & 2.5 Native Audio. Always finding the light.</p>
      </footer>
    </div>
  );
}

export default App;

