function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const LiveVoiceMode: React.FC<{ onClose: () => void }> = ({ onClose }) => {
  const [isActive, setIsActive] = useState(false);
  const [userSpeech, setUserSpeech] = useState('');
  const [aiSpeech, setAiSpeech] = useState('');
  const [isAiSpeaking, setIsAiSpeaking] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [permissionDenied, setPermissionDenied] = useState(false);

  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionRef = useRef<any>(null);

  useEffect(() => {
    requestPermissionsAndStart();
    return () => stopSession();
  }, []);

  const requestPermissionsAndStart = async () => {
    try {
      setError(null);
      setPermissionDenied(false);

      // Explicitly request microphone permission
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      startSession(stream);
    } catch (err: any) {
      console.error("Microphone permission error:", err);
      setPermissionDenied(true);
      setError("Microphone permission dismissed. Please allow access to talk to the Optimist.");
    }
  };

  const startSession = async (stream: MediaStream) => {
    try {
      const ai = getGeminiService();
      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsActive(true);
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);

            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const l = inputData.length;
              const int16 = new Int16Array(l);
              for (let i = 0; i < l; i++) {
                int16[i] = inputData[i] * 32768;
              }
              const pcmBlob = {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };

              sessionPromise.then((session) => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };

            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.inputTranscription) {
              setUserSpeech(prev => (prev + ' ' + message.serverContent?.inputTranscription?.text).trim());
            }
            if (message.serverContent?.outputTranscription) {
              setAiSpeech(prev => (prev + ' ' + message.serverContent?.outputTranscription?.text).trim());
            }
            if (message.serverContent?.turnComplete) {
              setUserSpeech('');
              setAiSpeech('');
            }

            const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (base64Audio) {
              setIsAiSpeaking(true);
              const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.onended = () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setIsAiSpeaking(false);
              };
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }

            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => {
                try { s.stop(); } catch(e) {}
              });
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setIsAiSpeaking(false);
            }
          },
          onerror: async (e: any) => {
            console.error("Live Error:", e);
            if (e?.message?.includes("Requested entity was not found")) {
              setError("API Key Error. Please re-select a paid API key.");
              if (typeof (window as any).aistudio?.openSelectKey === 'function') {
                await (window as any).aistudio.openSelectKey();
              }
            } else {
              setError("Connection error. Ensure your network is stable.");
            }
            setIsActive(false);
          },
          onclose: () => setIsActive(false),
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
          },
          systemInstruction: OPTIMIST_INSTRUCTION,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
        },
      });

      sessionRef.current = await sessionPromise;
    } catch (err: any) {
      console.error("Session start error:", err);
      setError("Failed to start voice session.");
    }
  };

  const stopSession = () => {
    if (sessionRef.current) {
      sessionRef.current.close();
    }
    inputAudioContextRef.current?.close();
    outputAudioContextRef.current?.close();
    sourcesRef.current.forEach(s => {
      try { s.stop(); } catch(e) {}
    });
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-white/95 backdrop-blur-xl transition-all duration-500">
      <div className="w-full max-w-xl p-8 flex flex-col items-center">
        <div className={`relative w-40 h-40 rounded-full flex items-center justify-center transition-all duration-700 ${isAiSpeaking ? 'scale-110 shadow-[0_0_60px_rgba(250,204,21,0.4)]' : 'scale-100 shadow-2xl'}`}>
          <div className={`absolute inset-0 rounded-full bg-yellow-400 opacity-20 animate-pulse ${isAiSpeaking ? 'block' : 'hidden'}`}></div>
          <div className="z-10 bg-yellow-100 text-yellow-600 rounded-full p-6 shadow-inner border border-yellow-200">
            <SunIcon className={`w-16 h-16 transition-transform duration-1000 ${isAiSpeaking ? 'animate-spin-slow' : ''}`} />
          </div>
        </div>

        <h2 className="mt-8 text-xl font-bold text-gray-800 text-center min-h-[1.5em] px-4">
          {error ? (
            <span className="text-red-500">{error}</span>
          ) : isActive ? (
            isAiSpeaking ? 'Finding the light...' : 'Listening to you...'
          ) : (
            'Preparing...'
          )}
        </h2>

        <div className="mt-8 w-full max-h-[30vh] overflow-y-auto space-y-4 px-4 scrollbar-hide">
          {userSpeech && (
            <div className="bg-blue-50 p-3 rounded-xl rounded-br-none border border-blue-100 self-end ml-auto max-w-[80%]">
              <p className="text-blue-800 text-sm italic">{userSpeech}</p>
            </div>
          )}
          {aiSpeech && (
            <div className="bg-yellow-50 p-4 rounded-xl rounded-bl-none border border-yellow-100 self-start mr-auto max-w-[90%] shadow-sm">
              <p className="text-yellow-900 font-medium text-base leading-relaxed">{aiSpeech}</p>
            </div>
          )}
        </div>

        <div className="mt-auto pt-8 flex gap-4 w-full justify-center">
          {permissionDenied && (
             <button
              onClick={requestPermissionsAndStart}
              className="px-6 py-2 bg-yellow-500 text-white rounded-full font-semibold shadow-md hover:bg-yellow-600 transition-all active:scale-95"
            >
              Allow Mic Access
            </button>
          )}
          <button
            onClick={onClose}
            className="px-6 py-2 bg-gray-100 text-gray-600 border border-gray-200 rounded-full font-semibold shadow-sm hover:bg-gray-200 transition-all active:scale-95"
          >
            {error ? 'Close' : 'End Voice Mode'}
          </button>
        </div>
      </div>
      <style>{`
        @keyframes spin-slow {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
        .animate-spin-slow {
          animation: spin-slow 15s linear infinite;
        }
        .scrollbar-hide::-webkit-scrollbar {
          display: none;
        }
      `}</style>
    </div>
  );
};

