import React, { useState, useCallback, useRef, useEffect } from 'react';
import { getGeminiService, OPTIMIST_INSTRUCTION } from './services/geminiService';
import { Status } from './types';
import Header from './components/Header';
import ProblemInput from './components/ProblemInput';
import LiveVoiceMode from './components/LiveVoiceMode';

interface Message {
  role: 'user' | 'model';
  text: string;
}

const GIF_MAP: Record<string, string> = {
  happy: "https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExNHJibjZpbnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5JmVwPXYxX2ludGVybmFsX2dpZl9ieV9pZCZjdD1n/l0MYt5jPR6QX5pnqM/giphy.gif",
  relax: "https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExNHJibjZpbnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5JmVwPXYxX2ludGVybmFsX2dpZl9ieV9pZCZjdD1n/3o7TKBupf8Hh6SndPa/giphy.gif",
  celebrate: "https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExNHJibjZpbnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5JmVwPXYxX2ludGVybmFsX2dpZl9ieV9pZCZjdD1n/26tPplGWjC0MrZePS/giphy.gif",
  nature: "https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExNHJibjZpbnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5JmVwPXYxX2ludGVybmFsX2dpZl9ieV9pZCZjdD1n/l4hLA4ALdmXqLHxXq/giphy.gif",
  proud: "https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExM3Y5dm5pY3I0eHh6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5JmVwPXYxX2ludGVybmFsX2dpZl9ieV9pZCZjdD1n/l3q2XhfQ8XxS1Mhkk/giphy.gif",
  hope: "https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExM3Y5dm5pY3I0eHh6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5JmVwPXYxX2ludGVybmFsX2dpZl9ieV9pZCZjdD1n/d1E2WyG_l5z6E/giphy.gif"
};

const MessageBubble: React.FC<{ msg: Message }> = ({ msg }) => {
  const isUser = msg.role === 'user';

  const gifRegex = /\[\[GIF: (\w+)\]\]/g;
  let gifMatch = gifRegex.exec(msg.text);
  const cleanText = msg.text.replace(gifRegex, '').trim();
  const gifUrl = gifMatch ? GIF_MAP[gifMatch[1].toLowerCase()] : null;

  return (
    <div className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-fade-in`}>
      <div className={`max-w-[85%] p-4 rounded-2xl shadow-sm transition-all duration-300 ${
        isUser 
          ? 'bg-blue-600 text-white rounded-br-none' 
          : 'bg-white text-gray-800 rounded-bl-none border border-yellow-100'
      }`}>
        <p className="leading-relaxed text-lg">{cleanText}</p>
        {gifUrl && (
          <div className="mt-3 rounded-xl overflow-hidden shadow-md animate-pop-in">
            <img src={gifUrl} alt="Reaction" className="w-full h-auto max-h-48 object-cover" />
          </div>
        )}
      </div>
    </div>
  );
};

function App() {
  const [problem, setProblem] = useState<string>('');
  const [history, setHistory] = useState<Message[]>([]);
  const [status, setStatus] = useState<Status>(Status.IDLE);
  const chatRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [history]);

  const handleSubmit = useCallback(async () => {
    if (!problem.trim()) return;

    const userMsg = problem.trim();
    setHistory(prev => [...prev, { role: 'user', text: userMsg }]);
    setProblem('');
    setStatus(Status.LOADING);

    try {
      const ai = getGeminiService();

      if (!chatRef.current) {
        chatRef.current = ai.chats.create({
          model: 'gemini-3-flash-preview',
          config: {
            systemInstruction: OPTIMIST_INSTRUCTION,
            temperature: 0.9,
            topP: 0.9,
          },
        });
      }

      const responseStream = await chatRef.current.sendMessageStream({ message: userMsg });

      setStatus(Status.SUCCESS);
      let fullText = "";
      setHistory(prev => [...prev, { role: 'model', text: "" }]);

      for await (const chunk of responseStream) {
        fullText += (chunk.text || "");
        setHistory(prev => {
          const newHistory = [...prev];
          newHistory[newHistory.length - 1] = { role: 'model', text: fullText };
          return newHistory;
        });
      }
    } catch (error) {
      console.error("Error generating content:", error);
      setStatus(Status.ERROR);
      setHistory(prev => [...prev, { role: 'model', text: "I'm so sorry, something went wrong. I'm still right here for you though! ❤️" }]);
    }
  }, [problem]);

  const handleClear = () => {
    setProblem('');
    setHistory([]);
    setStatus(Status.IDLE);
    chatRef.current = null;
  };

  const handleProblemChange = (newProblem: string) => {
    setProblem(newProblem);
    if(status === Status.ERROR) setStatus(Status.IDLE);
  };

  const startVoiceMode = async () => {
    if (typeof (window as any).aistudio?.hasSelectedApiKey === 'function') {
      const hasKey = await (window as any).aistudio.hasSelectedApiKey();
      if (!hasKey) await (window as any).aistudio.openSelectKey();
    }
    setStatus(Status.VOICE_MODE);
  };

  const stopVoiceMode = () => setStatus(Status.IDLE);

  return (
    <div className="min-h-screen bg-gradient-to-br from-yellow-50 to-blue-50 flex flex-col items-center p-4 sm:p-6 lg:p-8 font-sans transition-colors duration-1000">
      <div className="w-full max-w-2xl mx-auto flex flex-col items-center flex-1">
        <div className="mt-4 mb-8">
          <button
            onClick={startVoiceMode}
            className="flex items-center gap-2 px-6 py-2 bg-white border border-yellow-200 rounded-full shadow-sm hover:shadow-md text-yellow-700 font-medium transition-all transform hover:-translate-y-1 active:scale-95"
          >
            <span className="relative flex h-3 w-3">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-yellow-400 opacity-75"></span>
              <span className="relative inline-flex rounded-full h-3 w-3 bg-yellow-500"></span>
            </span>
            Talk to ELIX
          </button>
        </div>

        <Header />

        <div className="w-full flex-1 flex flex-col mt-8 overflow-hidden bg-white/40 backdrop-blur-sm rounded-3xl border border-white/60 shadow-xl">
          <div 
            ref={scrollRef}
            className="flex-1 overflow-y-auto p-6 space-y-6 scroll-smooth"
          >
            {history.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center text-gray-400 opacity-60">
                <p className="text-center italic">What's on your heart? ELIX is here. ❤️</p>
              </div>
            )}
            {history.map((msg, i) => (
              <MessageBubble key={i} msg={msg} />
            ))}
            {status === Status.LOADING && (
               <div className="flex justify-start animate-pulse">
                <div className="bg-yellow-100 w-12 h-6 rounded-full"></div>
               </div>
            )}
          </div>

          <div className="p-4 bg-white/60 border-t border-white/80">
            <ProblemInput 
              problem={problem}
              onProblemChange={handleProblemChange}
              onSubmit={handleSubmit}
              isLoading={status === Status.LOADING}
            />
            {history.length > 0 && (
               <button 
                onClick={handleClear}
                className="mt-2 text-xs text-gray-400 hover:text-gray-600 underline w-full text-center py-1 transition-colors"
              >
                New Chat with ELIX
              </button>
            )}
          </div>
        </div>
      </div>

      {status === Status.VOICE_MODE && (
        <LiveVoiceMode onClose={stopVoiceMode} />
      )}

      <footer className="text-center text-gray-400 text-[10px] mt-8 uppercase tracking-widest pb-4 space-y-2">
        <p>Your friend ELIX, powered by Gemini</p>
        <p className="max-w-md mx-auto normal-case tracking-normal text-[9px] opacity-75">
          ELIX is an AI companion, not a licensed therapist. If you are in a crisis, please seek professional help or contact a support hotline immediately.
        </p>
      </footer>

      <style>{`
        .animate-fade-in {
          animation: fadeIn 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }
        .animate-pop-in {
          animation: popIn 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
        }
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(12px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes popIn {
          from { opacity: 0; transform: scale(0.9); }
          to { opacity: 1; transform: scale(1); }
        }
        ::-webkit-scrollbar {
          width: 6px;
        }
        ::-webkit-scrollbar-track {
          background: transparent;
        }
        ::-webkit-scrollbar-thumb {
          background: #fde047;
          border-radius: 10px;
        }
      `}</style>
    </div>
  );
}

export default App;

