  const chatRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const lastUserMessage = useRef<string>('');

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [history, status]);

  const sendMessage = useCallback(async (messageText: string) => {
    if (!messageText.trim()) return;

    lastUserMessage.current = messageText.trim();
    setStatus(Status.LOADING);

    try {
      const ai = getGeminiService();

      if (!chatRef.current) {
        chatRef.current = ai.chats.create({
          model: 'gemini-flash-latest',
          config: {
            systemInstruction: OPTIMIST_INSTRUCTION,
            temperature: 0.9,
            topP: 0.9,
          },
        });
      }

      const responseStream = await chatRef.current.sendMessageStream({ message: messageText });

      setStatus(Status.SUCCESS);
      let fullText = "";

      // Add empty model message to history to stream into
      setHistory(prev => [...prev, { role: 'model', text: "" }]);

      for await (const chunk of responseStream) {
        fullText += (chunk.text || "");
        setHistory(prev => {
          const newHistory = [...prev];
          const lastMsg = newHistory[newHistory.length - 1];
          if (lastMsg && lastMsg.role === 'model') {
            newHistory[newHistory.length - 1] = { ...lastMsg, text: fullText };
          }
          return newHistory;
        });
      }
    } catch (error) {
      console.error("Error generating content:", error);
      setStatus(Status.ERROR);
      setHistory(prev => [...prev, { role: 'model', text: "I'm so sorry, I hit a little snag. But I'm still right here for you! ❤️" }]);
    }
  }, []);

  const handleSubmit = () => {
    const userMsg = problem.trim();
    if (!userMsg) return;
    setHistory(prev => [...prev, { role: 'user', text: userMsg }]);
    setProblem('');
    sendMessage(userMsg);
  };

  const handleRetry = () => {
    // Remove the last model message which was the error message
    setHistory(prev => prev.slice(0, -1));
    sendMessage(lastUserMessage.current);
  };

  const handleClear = () => {
    setProblem('');
    setHistory([]);
    setStatus(Status.IDLE);
    chatRef.current = null;
    lastUserMessage.current = '';
  };

  const handleProblemChange = (newProblem: string) => {
    setProblem(newProblem);
    if(status === Status.ERROR) setStatus(Status.IDLE);
  };

