        isUser 
          ? 'bg-blue-600 text-white rounded-br-none' 
          : 'bg-white text-gray-800 rounded-bl-none border border-yellow-100'
      } ${isError ? 'border-red-200 bg-red-50' : ''}`}>
        <p className="leading-relaxed text-lg whitespace-pre-wrap">{cleanText}</p>
