          </div>
        )}
        {isError && onRetry && (
          <button 
            onClick={onRetry}
            className="mt-3 px-4 py-1.5 bg-red-500 text-white text-xs font-semibold rounded-full hover:bg-red-600 transition-colors shadow-sm focus:outline-none focus:ring-2 focus:ring-red-400 focus:ring-offset-2"
          >
            Retry Connection
          </button>
        )}
      </div>
    </div>
  );
};

function App() {
  const [problem, setProblem] = useState<string>('');
  const [history, setHistory] = useState<Message[]>([]);
  const [status, setStatus] = useState<Status>(Status.IDLE);
  const chatRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const lastUserMessage = useRef<string>('');

  useEffect(() => {
    if (scrollRef.current) {
      const { scrollHeight, clientHeight } = scrollRef.current;
      scrollRef.current.scrollTo({
        top: scrollHeight - clientHeight,
        behavior: 'smooth'
      });
    }
  }, [history, status]);

  const sendMessage = useCallback(async (messageText: string) => {
    if (!messageText.trim()) return;

    lastUserMessage.current = messageText.trim();
    setStatus(Status.LOADING);

    try {
      const ai = getGeminiService();

      if (!chatRef.current) {
        chatRef.current = ai.chats.create({
          model: 'gemini-3-flash-preview',
          config: {
            systemInstruction: OPTIMIST_INSTRUCTION,
            temperature: 0.9,
            topP: 0.9,
          },
        });
      }

      const responseStream = await chatRef.current.sendMessageStream({ message: messageText });

      setStatus(Status.SUCCESS);
      let fullText = "";

      setHistory(prev => [...prev, { role: 'model', text: "" }]);

      for await (const chunk of responseStream) {
        fullText += (chunk.text || "");
        setHistory(prev => {
          const newHistory = [...prev];
          const lastMsg = newHistory[newHistory.length - 1];
          if (lastMsg && lastMsg.role === 'model') {
            newHistory[newHistory.length - 1] = { ...lastMsg, text: fullText };
          }
          return newHistory;
        });
      }
    } catch (error) {
      console.error("Error generating content:", error);
      setStatus(Status.ERROR);
      setHistory(prev => [...prev, { role: 'model', text: "I'm so sorry, I hit a little snag. But I'm still right here for you! Let's try that again. ❤️" }]);
    }
  }, []);

  const handleSubmit = () => {
    const userMsg = problem.trim();
    if (!userMsg) return;
    setHistory(prev => [...prev, { role: 'user', text: userMsg }]);
    setProblem('');
    sendMessage(userMsg);
  };

  const handleRetry = () => {
    setHistory(prev => prev.slice(0, -1));
    sendMessage(lastUserMessage.current);
  };

  const handleClear = () => {
    setProblem('');
    setHistory([]);
    setStatus(Status.IDLE);
    chatRef.current = null;
    lastUserMessage.current = '';
  };

  const handleProblemChange = (newProblem: string) => {
    setProblem(newProblem);
    if(status === Status.ERROR) setStatus(Status.IDLE);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-yellow-50 to-blue-50 flex flex-col items-center p-4 sm:p-6 lg:p-8 font-sans transition-colors duration-1000 overflow-hidden">
      <div className="w-full max-w-2xl mx-auto flex flex-col items-center h-[calc(100vh-2rem)] sm:h-[calc(100vh-4rem)]">
        <div className="pt-4 pb-4 flex-shrink-0">
          <Header />
        </div>

        <div className="w-full flex-1 flex flex-col min-h-0 overflow-hidden bg-white/40 backdrop-blur-sm rounded-3xl border border-white/60 shadow-xl">
          <div 
            ref={scrollRef}
            className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-6 scroll-smooth overscroll-contain"
          >
            {history.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center text-gray-400 opacity-60 px-4">
                <div className="text-center space-y-2">
                  <p className="italic leading-relaxed text-lg">
                    "Every cloud has a silver lining, and I'm here to help you find yours."
                  </p>
                  <span className="block font-semibold tracking-wider text-sm opacity-80">— ELIX</span>
                </div>
              </div>
            )}
            {history.map((msg, i) => {
              const isLastError = i === history.length - 1 && status === Status.ERROR && msg.role === 'model';
              return (
                <MessageBubble 
                  key={i} 
                  msg={msg} 
                  isError={isLastError} 
                  onRetry={isLastError ? handleRetry : undefined} 
                />
              );
            })}
            {status === Status.LOADING && (
               <div className="flex justify-start animate-pulse px-1">
                <div className="bg-yellow-100 w-12 h-6 rounded-full"></div>
               </div>
            )}
          </div>

          <div className="p-4 bg-white/60 border-t border-white/80 flex-shrink-0">
            <ProblemInput 
              problem={problem}
              onProblemChange={handleProblemChange}
              onSubmit={handleSubmit}
              isLoading={status === Status.LOADING}
            />
            {history.length > 0 && (
               <button 
                onClick={handleClear}
                className="mt-3 text-xs text-gray-400 hover:text-gray-600 underline w-full text-center py-1 transition-colors outline-none focus:text-gray-600"
              >
                Start a New Chat
              </button>
            )}
          </div>
        </div>
      </div>

      <footer className="text-center text-gray-400 text-[10px] mt-4 uppercase tracking-widest pb-4 space-y-2 flex-shrink-0">
        <p>Your companion ELIX • Powered by Gemini</p>
        <p className="max-w-md mx-auto normal-case tracking-normal text-[9px] opacity-75 px-6 leading-normal">
          ELIX is an AI companion, not a licensed professional. If you are in crisis, please seek professional help or contact a local support hotline immediately.
        </p>
      </footer>

      <style>{`
        .animate-fade-in {
          animation: fadeIn 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }
        .animate-pop-in {
          animation: popIn 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
        }
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(12px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes popIn {
          from { opacity: 0; transform: scale(0.9); }
          to { opacity: 1; transform: scale(1); }
        }
        ::-webkit-scrollbar {
          width: 5px;
        }
        ::-webkit-scrollbar-track {
          background: transparent;
        }
        ::-webkit-scrollbar-thumb {
          background: #fef08a;
          border-radius: 10px;
        }
        ::-webkit-scrollbar-thumb:hover {
          background: #fde047;
        }
        @supports (-webkit-touch-callout: none) {
          .h-screen {
            height: -webkit-fill-available;
          }
        }
      `}</style>
    </div>
  );
}

export default App;

