import React, { useState, useCallback, useRef, useEffect } from 'react';
import { getGeminiService, OPTIMIST_INSTRUCTION } from './services/geminiService';
import { Status } from './types';
import Header from './components/Header';
import ProblemInput from './components/ProblemInput';

interface Message {
  role: 'user' | 'model';
  text: string;
}

/**
 * Using cleaner Giphy IDs with i.giphy.com to avoid "Content not available" errors 
 * caused by expired tokens or referrer restrictions.
 */
const GIF_MAP: Record<string, string> = {
  happy: "https://i.giphy.com/media/v1.Y2lkPTc5MGI3NjExOHJibjZpbnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5JmVwPXYxX2ludGVybmFsX2dpZl9ieV9pZCZjdD1n/vLruUpvbszf20/giphy.gif",
  relax: "https://i.giphy.com/media/v1.Y2lkPTc5MGI3NjExOHJibjZpbnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5JmVwPXYxX2ludGVybmFsX2dpZl9ieV9pZCZjdD1n/13jJIYp4D8A9Xy/giphy.gif",
  celebrate: "https://i.giphy.com/media/v1.Y2lkPTc5MGI3NjExOHJibjZpbnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5JmVwPXYxX2ludGVybmFsX2dpZl9ieV9pZCZjdD1n/26tPplGWjC0MrZePS/giphy.gif",
  nature: "https://i.giphy.com/media/v1.Y2lkPTc5MGI3NjExOHJibjZpbnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5JmVwPXYxX2ludGVybmFsX2dpZl9ieV9pZCZjdD1n/l4hLA4ALdmXqLHxXq/giphy.gif",
  proud: "https://i.giphy.com/media/v1.Y2lkPTc5MGI3NjExOHJibjZpbnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5JmVwPXYxX2ludGVybmFsX2dpZl9ieV9pZCZjdD1n/l3q2XhfQ8XxS1Mhkk/giphy.gif",
  hope: "https://i.giphy.com/media/v1.Y2lkPTc5MGI3NjExOHJibjZpbnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5bmZ6bnR5JmVwPXYxX2ludGVybmFsX2dpZl9ieV9pZCZjdD1n/d1E2WyG_l5z6E/giphy.gif"
};

const MessageBubble: React.FC<{ msg: Message; isError?: boolean; onRetry?: () => void }> = ({ msg, isError, onRetry }) => {
  const isUser = msg.role === 'user';
  const [imgLoadError, setImgLoadError] = useState(false);

  const gifRegex = /\[\[GIF: (\w+)\]\]/g;
  let gifMatch = gifRegex.exec(msg.text);
  const cleanText = msg.text.replace(gifRegex, '').trim();
  const gifUrl = gifMatch ? GIF_MAP[gifMatch[1].toLowerCase()] : null;

  return (
    <div className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-fade-in px-1`}>
