            newHistory[newHistory.length - 1] = { ...lastMsg, text: fullText };
          }
          return newHistory;
        });
      }
    } catch (error: any) {
      console.error(`Attempt ${retryCount + 1} failed:`, error);

      // Handle automatic retries for network-related errors
      if (retryCount < MAX_RETRIES && (error.message?.includes('fetch') || !navigator.onLine)) {
