import ProblemInput from './components/ProblemInput';

interface Message {
  role: 'user' | 'model';
  text: string;
}

const MessageBubble: React.FC<{ msg: Message; isError?: boolean; onRetry?: () => void }> = ({ msg, isError, onRetry }) => {
  const isUser = msg.role === 'user';

  return (
    <div className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-fade-in px-1`}>
      <div className={`max-w-[85%] p-5 rounded-[2rem] shadow-xl transition-all duration-500 hover:shadow-2xl ${
        isUser 
          ? 'bg-gradient-to-br from-blue-500 to-indigo-600 text-white rounded-br-none shadow-blue-100' 
          : 'bg-white/90 backdrop-blur-md text-gray-800 rounded-bl-none border border-yellow-50 shadow-yellow-100/50'
      } ${isError ? 'border-red-100 bg-red-50' : ''}`}>
        <p className="leading-relaxed text-lg whitespace-pre-wrap font-medium tracking-tight">
          {msg.text}
        </p>

        {isError && onRetry && (
          <button 
            onClick={onRetry}
            className="mt-4 px-6 py-2 bg-red-500 text-white text-xs font-black rounded-full hover:bg-red-600 transition-all shadow-md active:scale-95 flex items-center gap-2"
          >
            <span>Try Again</span>
            <span>✨</span>
          </button>
        )}
      </div>
    </div>
  );
};

function App() {
  const [problem, setProblem] = useState<string>('');
  const [history, setHistory] = useState<Message[]>([]);
  const [status, setStatus] = useState<Status>(Status.IDLE);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const chatRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const lastUserMessage = useRef<string>('');

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      const { scrollHeight, clientHeight } = scrollRef.current;
      scrollRef.current.scrollTo({
        top: scrollHeight - clientHeight,
        behavior: 'smooth'
      });
    }
  }, [history, status]);

  const sendMessage = useCallback(async (messageText: string, retryCount = 0) => {
    if (!messageText.trim()) return;

    const MAX_RETRIES = 2;
    lastUserMessage.current = messageText.trim();
    setStatus(Status.LOADING);

    if (!navigator.onLine) {
        setStatus(Status.ERROR);
        setHistory(prev => [...prev, { role: 'model', text: "I can't seem to reach the clouds right now! ☁️ Please check your internet connection and try again. ✨💖" }]);
        return;
    }

    try {
      const ai = getGeminiService();

      if (!chatRef.current) {
        chatRef.current = ai.chats.create({
          model: 'gemini-3-flash-preview',
          config: {
            systemInstruction: OPTIMIST_INSTRUCTION,
            temperature: 0.95,
            topP: 0.95,
          },
        });
      }

      const responseStream = await chatRef.current.sendMessageStream({ message: messageText });

      setStatus(Status.SUCCESS);
      let fullText = "";

      setHistory(prev => [...prev, { role: 'model', text: "" }]);

      for await (const chunk of responseStream) {
        const chunkText = chunk.text || "";
        fullText += chunkText;

        setHistory(prev => {
          const newHistory = [...prev];
          const lastMsg = newHistory[newHistory.length - 1];
          if (lastMsg && lastMsg.role === 'model') {
            newHistory[newHistory.length - 1] = { ...lastMsg, text: fullText };
          }
          return newHistory;
        });
      }
    } catch (error: any) {
      console.error(`Attempt ${retryCount + 1} failed:`, error);

      if (retryCount < MAX_RETRIES && (error.message?.includes('fetch') || !navigator.onLine)) {
        const delay = Math.pow(2, retryCount) * 1000;
        setTimeout(() => sendMessage(messageText, retryCount + 1), delay);
        return;
      }

      setStatus(Status.ERROR);
      let errorText = "I'm so sorry, I hit a little snag. But I'm still right here for you! Let's try that again. ✨💖✨";
      if (error?.message?.includes("ELIX_MISSING_API_KEY")) {
        errorText = "I can't seem to find my API key sunshine! ☀️ Please check your environment variables so I can help you find those silver linings. ✨";
      }

      setHistory(prev => [...prev, { role: 'model', text: errorText }]);
    }
  }, []);

  const handleSubmit = () => {
    const userMsg = problem.trim();
    if (!userMsg) return;
    setHistory(prev => [...prev, { role: 'user', text: userMsg }]);
    setProblem('');
    sendMessage(userMsg);
  };

  const handleRetry = () => {
    setHistory(prev => {
        const last = prev[prev.length - 1];
        return last?.role === 'model' ? prev.slice(0, -1) : prev;
    });
    sendMessage(lastUserMessage.current);
  };

  const handleClear = () => {
    setProblem('');
    setHistory([]);
    setStatus(Status.IDLE);
    chatRef.current = null;
    lastUserMessage.current = '';
  };

  const handleProblemChange = (newProblem: string) => {
    setProblem(newProblem);
    if(status === Status.ERROR) setStatus(Status.IDLE);
  };

  return (
    <div className="min-h-screen bg-[#FFFCF5] relative flex flex-col items-center p-4 sm:p-6 lg:p-8 font-sans transition-all duration-1000 overflow-hidden text-gray-800 selection:bg-yellow-100">

      {/* Background Sparkles Decorations */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none opacity-40">
        <div className="absolute top-[10%] left-[5%] text-4xl animate-float-slow">✨</div>
        <div className="absolute top-[20%] right-[8%] text-3xl animate-float-medium">🌟</div>
        <div className="absolute bottom-[15%] left-[10%] text-5xl animate-float-slow">🌻</div>
        <div className="absolute bottom-[25%] right-[5%] text-4xl animate-float-medium">💖</div>
        <div className="absolute top-[40%] right-[15%] text-2xl animate-float-fast">☀️</div>
      </div>

      <div className="w-full max-w-2xl mx-auto flex flex-col items-center h-[calc(100vh-2rem)] sm:h-[calc(100vh-4rem)] z-10">

        {!isOnline && (
          <div className="fixed top-4 left-1/2 -translate-x-1/2 z-50 bg-orange-400 text-white px-6 py-2 rounded-full text-xs font-black shadow-xl animate-pulse tracking-widest">
            STAYING POSITIVE • OFFLINE
          </div>
        )}

        <div className="pt-2 pb-6 flex-shrink-0">
          <Header />
        </div>

        <div className="w-full flex-1 flex flex-col min-h-0 overflow-hidden bg-white/60 backdrop-blur-2xl rounded-[3rem] border border-white/80 shadow-[0_25px_60px_rgba(234,179,8,0.06)]">
          <div 
            ref={scrollRef}
            className="flex-1 overflow-y-auto p-4 sm:p-10 space-y-10 scroll-smooth overscroll-contain no-scrollbar"
          >
            {history.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center text-gray-400 opacity-60 px-6 select-none animate-float-medium">
                <div className="text-center space-y-6">
                  <div className="text-7xl filter drop-shadow-xl animate-bounce-subtle">✨☀️✨</div>
                  <p className="italic leading-relaxed text-2xl max-w-sm font-light text-gray-700">
                    "Every cloud has a silver lining, and I'm here to help you find yours."
                  </p>
                  <div className="flex flex-col gap-3">
                    <span className="block font-black tracking-[0.4em] text-[10px] uppercase text-yellow-600">ELIX • Your Personal Bestie</span>
                    <div className="flex justify-center gap-3 text-2xl opacity-80">🫧 🪐 🐚 🕊️</div>
                  </div>
                </div>
              </div>
            )}
            {history.map((msg, i) => {
              const isLastError = i === history.length - 1 && status === Status.ERROR && msg.role === 'model';
              return (
                <MessageBubble 
                  key={i} 
                  msg={msg} 
                  isError={isLastError} 
                  onRetry={isLastError ? handleRetry : undefined} 
                />
              );
            })}
            {status === Status.LOADING && (
               <div className="flex justify-start px-2">
                <div className="bg-yellow-50/80 backdrop-blur-sm w-24 h-12 rounded-full flex items-center justify-center space-x-2 border border-yellow-100 shadow-sm">
                  <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full animate-bounce [animation-duration:0.6s]"></div>
                  <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full animate-bounce [animation-delay:0.2s] [animation-duration:0.6s]"></div>
                  <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full animate-bounce [animation-delay:0.4s] [animation-duration:0.6s]"></div>
                </div>
               </div>
            )}
          </div>

          <div className="p-8 bg-white/40 border-t border-white/80 flex-shrink-0">
            <ProblemInput 
              problem={problem}
              onProblemChange={handleProblemChange}
              onSubmit={handleSubmit}
              isLoading={status === Status.LOADING}
            />
            {history.length > 0 && (
               <button 
                onClick={handleClear}
