interface ProblemInputProps {
  problem: string;
  onProblemChange: (problem: string) => void;
  onSubmit: () => void;
  isLoading: boolean;
}

const ProblemInput: React.FC<ProblemInputProps> = ({ problem, onProblemChange, onSubmit, isLoading }) => {
  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        onSubmit();
    }
  };

  return (
    <div className="w-full">
      <div className="relative flex items-center gap-3">
        <textarea
          value={problem}
          onChange={(e) => onProblemChange(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="What's on your heart?"
          className="flex-1 min-h-[64px] max-h-32 p-5 text-gray-900 font-bold bg-yellow-50/60 border-2 border-yellow-200 rounded-[2rem] resize-none focus:outline-none focus:ring-8 focus:ring-yellow-100/50 focus:border-yellow-400 focus:bg-white transition-all shadow-inner text-lg placeholder:text-yellow-400/40"
          disabled={isLoading}
          rows={1}
        />
        <button
          onClick={onSubmit}
          disabled={isLoading || !problem.trim()}
          className="w-16 h-16 bg-yellow-400 text-white rounded-[1.5rem] shadow-xl hover:bg-yellow-500 hover:shadow-yellow-200 disabled:bg-gray-100 disabled:text-gray-300 transition-all flex items-center justify-center flex-shrink-0 active:scale-90"
          aria-label="Send"
        >
          {isLoading ? (
             <svg className="animate-spin h-7 w-7" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
              <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
              <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
            </svg>
          ) : (
            <SparklesIcon className="w-7 h-7" />
          )}
        </button>
      </div>
    </div>
  );
};

