        <div className="absolute bottom-[25%] right-[8%] text-2xl animate-float-medium">💖</div>
      </div>

      <div className="w-full max-w-xl mx-auto flex flex-col items-center h-full z-10 px-4 py-3 sm:py-6">

        {!isOnline && (
          <div className="fixed top-1 left-1/2 -translate-x-1/2 z-50 bg-orange-400 text-white px-3 py-0.5 rounded-full text-[8px] font-black shadow-lg animate-pulse tracking-widest uppercase">
