        <div className="w-full flex-1 flex flex-col min-h-0 overflow-hidden bg-white/60 backdrop-blur-2xl rounded-[2rem] border border-white/80 shadow-[0_15px_40px_rgba(234,179,8,0.05)]">
          <div 
            ref={scrollRef}
            className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-4 sm:space-y-6 scroll-smooth overscroll-contain custom-scrollbar"
          >
            {history.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center text-gray-400 opacity-60 px-4 select-none animate-float-medium">
