          onClick={onSubmit}
          disabled={isLoading || !problem.trim()}
          className="w-12 h-12 sm:w-14 sm:h-14 bg-yellow-400 text-white rounded-[1.25rem] shadow-lg hover:bg-yellow-500 hover:shadow-yellow-200 disabled:bg-gray-100 disabled:text-gray-300 transition-all flex items-center justify-center flex-shrink-0 active:scale-90"
