        <div className="absolute top-[10%] right-[10%] text-lg animate-float-medium">🌟</div>
        <div className="absolute bottom-[15%] left-[8%] text-2xl animate-float-slow">🌻</div>
        <div className="absolute bottom-[20%] right-[8%] text-xl animate-float-medium">💖</div>
      </div>

      <div className="w-full max-w-lg mx-auto flex flex-col items-center h-full z-10 px-4 py-2 sm:py-4">

        {!isOnline && (
          <div className="fixed top-0.5 left-1/2 -translate-x-1/2 z-50 bg-orange-400 text-white px-3 py-0.5 rounded-full text-[7px] font-black shadow-lg animate-pulse tracking-widest uppercase">
            Offline
          </div>
        )}

        <div className="pb-1.5 flex-shrink-0">
