  onProblemChange: (problem: string) => void;
  onSubmit: () => void;
  isLoading: boolean;
}

const ProblemInput: React.FC<ProblemInputProps> = ({ problem, onProblemChange, onSubmit, isLoading }) => {
  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        onSubmit();
    }
  };

  return (
    <div className="w-full">
      <div className="relative flex items-center gap-2">
        <textarea
          value={problem}
          onChange={(e) => onProblemChange(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="What's on your heart?"
          className="flex-1 min-h-[44px] max-h-20 p-3 text-gray-900 font-bold bg-yellow-50/60 border-2 border-yellow-200 rounded-[1.25rem] resize-none focus:outline-none focus:ring-4 focus:ring-yellow-100/30 focus:border-yellow-400 focus:bg-white transition-all shadow-inner text-sm sm:text-base placeholder:text-yellow-400/30"
          disabled={isLoading}
          rows={1}
        />
        <button
          onClick={onSubmit}
          disabled={isLoading || !problem.trim()}
          className="w-11 h-11 sm:w-12 sm:h-12 bg-yellow-400 text-white rounded-[1rem] shadow-md hover:bg-yellow-500 hover:shadow-yellow-200 disabled:bg-gray-100 disabled:text-gray-300 transition-all flex items-center justify-center flex-shrink-0 active:scale-90"
          aria-label="Send"
        >
          {isLoading ? (
             <svg className="animate-spin h-5 w-5" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
              <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
              <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
            </svg>
          ) : (
            <SparklesIcon className="w-5 h-5 sm:w-6 sm:h-6" />
          )}
        </button>
      </div>
    </div>
  );
};

export default ProblemInput;

