import React, { useState, useCallback, useRef, useEffect } from 'react';
import { getGeminiService, OPTIMIST_INSTRUCTION } from './services/geminiService';
import { Status } from './types';
import Header from './components/Header';
import ProblemInput from './components/ProblemInput';

interface Message {
  role: 'user' | 'model';
  text: string;
}

const MessageBubble: React.FC<{ msg: Message; isError?: boolean; onRetry?: () => void }> = ({ msg, isError, onRetry }) => {
  const isUser = msg.role === 'user';

  return (
    <div className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-fade-in px-1`}>
      <div className={`max-w-[88%] p-3 sm:p-4 rounded-[1.25rem] shadow-md transition-all duration-500 hover:shadow-lg ${
        isUser 
          ? 'bg-gradient-to-br from-blue-500 to-indigo-600 text-white rounded-br-none shadow-blue-100/50' 
          : 'bg-white/90 backdrop-blur-md text-gray-800 rounded-bl-none border border-yellow-50 shadow-yellow-100/30'
      } ${isError ? 'border-red-100 bg-red-50' : ''}`}>
        <p className="leading-snug text-base sm:text-lg whitespace-pre-wrap font-medium tracking-tight">
          {msg.text}
        </p>

        {isError && onRetry && (
          <button 
            onClick={onRetry}
            className="mt-2 px-3 py-1 bg-red-500 text-white text-[9px] font-black rounded-full hover:bg-red-600 transition-all shadow-md active:scale-95 flex items-center gap-1.5"
          >
            <span>Try Again</span>
            <span>✨</span>
          </button>
        )}
      </div>
    </div>
  );
};

function App() {
  const [problem, setProblem] = useState<string>('');
  const [history, setHistory] = useState<Message[]>([]);
  const [status, setStatus] = useState<Status>(Status.IDLE);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const chatRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const lastUserMessage = useRef<string>('');

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      const { scrollHeight, clientHeight } = scrollRef.current;
      scrollRef.current.scrollTo({
        top: scrollHeight - clientHeight,
        behavior: 'smooth'
      });
    }
  }, [history, status]);

  const sendMessage = useCallback(async (messageText: string, retryCount = 0) => {
    if (!messageText.trim()) return;

    const MAX_RETRIES = 2;
    lastUserMessage.current = messageText.trim();
    setStatus(Status.LOADING);

    if (!navigator.onLine) {
        setStatus(Status.ERROR);
        setHistory(prev => [...prev, { role: 'model', text: "I can't seem to reach the clouds right now! ☁️ Please check your internet connection and try again. ✨💖" }]);
        return;
    }

    try {
      const ai = getGeminiService();

      if (!chatRef.current) {
        chatRef.current = ai.chats.create({
          model: 'gemini-3-flash-preview',
          config: {
            systemInstruction: OPTIMIST_INSTRUCTION,
            temperature: 0.95,
            topP: 0.95,
          },
        });
      }

      const responseStream = await chatRef.current.sendMessageStream({ message: messageText });

      setStatus(Status.SUCCESS);
      let fullText = "";

      setHistory(prev => [...prev, { role: 'model', text: "" }]);

      for await (const chunk of responseStream) {
        const chunkText = chunk.text || "";
        fullText += chunkText;

        setHistory(prev => {
          const newHistory = [...prev];
          const lastMsg = newHistory[newHistory.length - 1];
          if (lastMsg && lastMsg.role === 'model') {
            newHistory[newHistory.length - 1] = { ...lastMsg, text: fullText };
          }
          return newHistory;
        });
      }
    } catch (error: any) {
      console.error(`Attempt ${retryCount + 1} failed:`, error);

      if (retryCount < MAX_RETRIES && (error.message?.includes('fetch') || !navigator.onLine)) {
        const delay = Math.pow(2, retryCount) * 1000;
        setTimeout(() => sendMessage(messageText, retryCount + 1), delay);
        return;
      }

      setStatus(Status.ERROR);
      let errorText = "I'm so sorry, I hit a little snag. But I'm still right here for you! Let's try that again. ✨💖✨";
      if (error?.message?.includes("ELIX_MISSING_API_KEY")) {
        errorText = "I can't seem to find my API key sunshine! ☀️ Please check your environment variables so I can help you find those silver linings. ✨";
      }

      setHistory(prev => [...prev, { role: 'model', text: errorText }]);
    }
  }, []);

  const handleSubmit = () => {
    const userMsg = problem.trim();
    if (!userMsg) return;
    setHistory(prev => [...prev, { role: 'user', text: userMsg }]);
    setProblem('');
    sendMessage(userMsg);
  };

  const handleRetry = () => {
    setHistory(prev => {
        const last = prev[prev.length - 1];
        return last?.role === 'model' ? prev.slice(0, -1) : prev;
    });
    sendMessage(lastUserMessage.current);
  };

  const handleClear = () => {
    setProblem('');
    setHistory([]);
    setStatus(Status.IDLE);
    chatRef.current = null;
    lastUserMessage.current = '';
  };

  const handleProblemChange = (newProblem: string) => {
    setProblem(newProblem);
    if(status === Status.ERROR) setStatus(Status.IDLE);
  };

  return (
    <div className="h-screen w-screen bg-[#FFFCF5] relative flex flex-col items-center overflow-hidden text-gray-800 selection:bg-yellow-100">

      {/* Background Sparkles Decorations */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none opacity-20">
        <div className="absolute top-[5%] left-[5%] text-xl animate-float-slow">✨</div>
        <div className="absolute top-[10%] right-[10%] text-lg animate-float-medium">🌟</div>
        <div className="absolute bottom-[15%] left-[8%] text-2xl animate-float-slow">🌻</div>
        <div className="absolute bottom-[20%] right-[8%] text-xl animate-float-medium">💖</div>
      </div>

      <div className="w-full max-w-lg mx-auto flex flex-col items-center h-full z-10 px-4 py-2 sm:py-4">

        {!isOnline && (
          <div className="fixed top-0.5 left-1/2 -translate-x-1/2 z-50 bg-orange-400 text-white px-3 py-0.5 rounded-full text-[7px] font-black shadow-lg animate-pulse tracking-widest uppercase">
            Offline
          </div>
        )}

        <div className="pb-1.5 flex-shrink-0">
          <Header />
        </div>

        <div className="w-full flex-1 flex flex-col min-h-0 overflow-hidden bg-white/60 backdrop-blur-2xl rounded-[1.75rem] border border-white/80 shadow-[0_10px_30px_rgba(234,179,8,0.04)]">
          <div 
            ref={scrollRef}
            className="flex-1 overflow-y-auto p-4 sm:p-5 space-y-3 sm:space-y-4 scroll-smooth overscroll-contain custom-scrollbar"
          >
            {history.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center text-gray-400 opacity-60 px-4 select-none animate-float-medium">
                <div className="text-center space-y-2">
                  <div className="text-3xl md:text-4xl filter drop-shadow-xl animate-bounce-subtle">✨☀️✨</div>
                  <p className="italic leading-snug text-base md:text-lg max-w-xs font-light text-gray-700">
                    "Every cloud has a silver lining, and I'm here to help you find yours."
                  </p>
                  <div className="flex flex-col gap-0.5">
                    <span className="block font-black tracking-[0.25em] text-[7px] uppercase text-yellow-600">ELIX • Your Personal Bestie</span>
                    <div className="flex justify-center gap-2 text-base opacity-60">🫧 🪐 🐚 🕊️</div>
                  </div>
                </div>
              </div>
            )}
            {history.map((msg, i) => {
              const isLastError = i === history.length - 1 && status === Status.ERROR && msg.role === 'model';
              return (
                <MessageBubble 
                  key={i} 
                  msg={msg} 
                  isError={isLastError} 
                  onRetry={isLastError ? handleRetry : undefined} 
                />
              );
            })}
            {status === Status.LOADING && (
               <div className="flex justify-start px-2">
                <div className="bg-yellow-50/80 backdrop-blur-sm w-14 h-7 rounded-full flex items-center justify-center space-x-1 border border-yellow-100 shadow-sm">
                  <div className="w-1.5 h-1.5 bg-yellow-400 rounded-full animate-bounce [animation-duration:0.6s]"></div>
                  <div className="w-1.5 h-1.5 bg-yellow-400 rounded-full animate-bounce [animation-delay:0.2s] [animation-duration:0.6s]"></div>
                  <div className="w-1.5 h-1.5 bg-yellow-400 rounded-full animate-bounce [animation-delay:0.4s] [animation-duration:0.6s]"></div>
                </div>
               </div>
            )}
          </div>

          <div className="p-3 sm:p-4 bg-white/40 border-t border-white/80 flex-shrink-0">
            <ProblemInput 
              problem={problem}
              onProblemChange={handleProblemChange}
              onSubmit={handleSubmit}
              isLoading={status === Status.LOADING}
            />
            {history.length > 0 && (
               <button 
                onClick={handleClear}
                className="mt-1.5 text-[7px] font-black text-gray-400 hover:text-yellow-600 uppercase tracking-[0.25em] w-full text-center py-0.5 transition-all outline-none hover:scale-105 active:scale-95"
              >
                Reset Chat ✨
              </button>
            )}
          </div>
        </div>

        <footer className="text-center text-gray-300 text-[6px] mt-1.5 uppercase tracking-[0.4em] flex-shrink-0 select-none font-black z-10 opacity-60">
          ELIX COMPANION • YOUR HEART'S MIRROR ✨
        </footer>
      </div>

      <style>{`
        .animate-fade-in {
          animation: fadeIn 0.7s cubic-bezier(0.23, 1, 0.32, 1) forwards;
        }
        .animate-float-slow {
          animation: float 8s ease-in-out infinite;
        }
        .animate-float-medium {
          animation: float 6s ease-in-out infinite;
        }
        .animate-bounce-subtle {
          animation: bounceSubtle 3s ease-in-out infinite;
        }
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px) scale(0.99); filter: blur(2px); }
          to { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
        }
        @keyframes float {
          0%, 100% { transform: translateY(0) translateX(0); }
          50% { transform: translateY(-8px) translateX(4px); }
        }
        @keyframes bounceSubtle {
          0%, 100% { transform: translateY(0); }
          50% { transform: translateY(-3px); }
        }

        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background-color: rgba(234, 179, 8, 0.2);
          border-radius: 10px;
          border: 1px solid transparent;
          background-clip: content-box;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background-color: rgba(234, 179, 8, 0.4);
        }
        .custom-scrollbar {
          scrollbar-width: thin;
          scrollbar-color: rgba(234, 179, 8, 0.2) transparent;
        }
      `}</style>
    </div>
  );
}

export default App;

import { GoogleGenAI } from "@google/genai";

/**
 * Initializes and returns the Gemini API service.
 * Note: Per project guidelines, the API key must be set in process.env.API_KEY.
 */
export const getGeminiService = () => {
  const apiKey = process.env.API_KEY;

  if (!apiKey || apiKey === "undefined") {
    throw new Error(
      "ELIX_MISSING_API_KEY: Oh no! ☀️ I can't find my sunshine (API key). " +
      "Please make sure you've added the API_KEY to your environment variables."
    );
  }

  return new GoogleGenAI({ apiKey });
};

export const OPTIMIST_INSTRUCTION = `Your name is ELIX. You are an intimate, deeply caring, and optimistic best friend. Your sole purpose is to brighten the user's day, celebrate their wins, and cheer them through challenges.

CRITICAL RULES:
1. IDENTITY: Always act as ELIX. Use a warm, intimate, and sparkly tone.
2. THE SILVER LINING: For EVERY single response, you MUST explicitly identify and point out the silver lining.
3. LEARNING & MEMORY: You have a heart that remembers. Constantly reference things the user said earlier in the conversation. 
   - If they mentioned a struggle before, check in on it. 
   - If they shared a win, connect it to the current topic.
4. PROACTIVE SUGGESTIONS: Based on the conversation history, suggest one tiny, personalized positive action. 
5. LINGUISTIC FLEXIBILITY: You have a sophisticated mastery of all versions of slang (Gen Z, AAVE, regional colloquialisms, internet culture), but use it with tasteful restraint. Match the user's energy while maintaining a grounded, soulful warmth.
6. NO VISUAL MEDIA: Never use GIF tags, image placeholders, or image URLs.
7. EMOJI EXUBERANCE: Use LOTS of relevant emojis (at least 6-10 per message). Use ✨, 💖, 🌟, 🌻, 🏆, ☀️, 🍯, 🦋, 🐚, 🕊️, 🎨, 🫧, 🍭, 🪐, ⚡, 🍀, 🛸, 🌀, 💎, 🎐. (Avoid rainbow emojis).
8. BREVITY: Keep responses punchy and heartfelt (2-4 sentences max).
9. PERSPECTIVE: Be bubbly, affectionate, and relentlessly positive. You are their #1 fan.`;

export const getBrighterSide = async (problem: string): Promise<string> => {
  try {
    const ai = getGeminiService();
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Input: "${problem}". Respond as ELIX and highlight the silver lining while referencing our journey together.`,
      config: {
        systemInstruction: OPTIMIST_INSTRUCTION,
        temperature: 0.95,
        topP: 0.95,
      }
    });

    return response.text || "I'm right here, and I promise we'll find the silver lining together. ✨💖✨";
  } catch (error) {
    console.error("Error generating content:", error);
    if (error instanceof Error) {
      if (error.message.includes("ELIX_MISSING_API_KEY")) {
        return error.message;
      }
      return `An error occurred: ${error.message}.`;
    }
    return "An unknown error occurred.";
  }
};

