          background-color: rgba(15, 23, 42, 0.9);
        }
        .custom-scrollbar {
          scrollbar-width: thin;
          scrollbar-color: rgba(15, 23, 42, 0.7) transparent;
        }
      `}</style>
    </div>
  );
}

