import React, { useState, useCallback, useRef, useEffect } from 'react';
import { getGeminiService, OPTIMIST_INSTRUCTION } from './services/geminiService';
import { Status } from './types';
import Header from './components/Header';
import ProblemInput from './components/ProblemInput';

interface Message {
  role: 'user' | 'model';
  text: string;
}

const MessageBubble: React.FC<{ msg: Message; isError?: boolean; onRetry?: () => void }> = ({ msg, isError, onRetry }) => {
  const isUser = msg.role === 'user';

  return (
    <div className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-fade-in px-1`}>
      <div className={`max-w-[88%] p-3 sm:p-4 rounded-[1.25rem] shadow-md transition-all duration-500 hover:shadow-lg ${
        isUser 
          ? 'bg-gradient-to-br from-blue-500 to-indigo-600 text-white rounded-br-none shadow-blue-100/50' 
          : 'bg-white/90 backdrop-blur-md text-gray-800 rounded-bl-none border border-yellow-50 shadow-yellow-100/30'
      } ${isError ? 'border-red-100 bg-red-50' : ''}`}>
        <p className="leading-snug text-base sm:text-lg whitespace-pre-wrap font-medium tracking-tight">
          {msg.text}
        </p>

        {isError && onRetry && (
          <button 
            onClick={onRetry}
            className="mt-2 px-3 py-1 bg-red-500 text-white text-[9px] font-black rounded-full hover:bg-red-600 transition-all shadow-md active:scale-95 flex items-center gap-1.5"
          >
            <span>Try Again</span>
            <span>✨</span>
          </button>
        )}
      </div>
    </div>
  );
};

function App() {
  const [problem, setProblem] = useState<string>('');
  const [history, setHistory] = useState<Message[]>([]);
  const [status, setStatus] = useState<Status>(Status.IDLE);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const chatRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const lastUserMessage = useRef<string>('');

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      const { scrollHeight, clientHeight } = scrollRef.current;
      scrollRef.current.scrollTo({
        top: scrollHeight - clientHeight,
        behavior: 'smooth'
      });
    }
  }, [history, status]);

  const sendMessage = useCallback(async (messageText: string, retryCount = 0) => {
    if (!messageText.trim()) return;

    const MAX_RETRIES = 2;
    lastUserMessage.current = messageText.trim();
    setStatus(Status.LOADING);

    if (!navigator.onLine) {
        setStatus(Status.ERROR);
        setHistory(prev => [...prev, { role: 'model', text: "I can't seem to reach the clouds right now! ☁️ Please check your internet connection and try again. ✨💖" }]);
        return;
    }

    try {
      const ai = getGeminiService();

      if (!chatRef.current) {
        chatRef.current = ai.chats.create({
          model: 'gemini-3-flash-preview',
          config: {
            systemInstruction: OPTIMIST_INSTRUCTION,
            temperature: 0.95,
            topP: 0.95,
          },
        });
      }

      const responseStream = await chatRef.current.sendMessageStream({ message: messageText });

      setStatus(Status.SUCCESS);
      let fullText = "";

      setHistory(prev => [...prev, { role: 'model', text: "" }]);

      for await (const chunk of responseStream) {
        const chunkText = chunk.text || "";
        fullText += chunkText;

        setHistory(prev => {
          const newHistory = [...prev];
          const lastMsg = newHistory[newHistory.length - 1];
          if (lastMsg && lastMsg.role === 'model') {
            newHistory[newHistory.length - 1] = { ...lastMsg, text: fullText };
          }
          return newHistory;
        });
      }
    } catch (error: any) {
      console.error(`Attempt ${retryCount + 1} failed:`, error);

      if (retryCount < MAX_RETRIES && (error.message?.includes('fetch') || !navigator.onLine)) {
        const delay = Math.pow(2, retryCount) * 1000;
        setTimeout(() => sendMessage(messageText, retryCount + 1), delay);
        return;
      }

      setStatus(Status.ERROR);
      let errorText = "I'm so sorry, I hit a little snag. But I'm still right here for you! Let's try that again. ✨💖✨";
      if (error?.message?.includes("ELIX_MISSING_API_KEY")) {
        errorText = "I can't seem to find my API key sunshine! ☀️ Please check your environment variables so I can help you find those silver linings. ✨";
      }

      setHistory(prev => [...prev, { role: 'model', text: errorText }]);
    }
  }, []);

  const handleSubmit = () => {
    const userMsg = problem.trim();
    if (!userMsg) return;
    setHistory(prev => [...prev, { role: 'user', text: userMsg }]);
    setProblem('');
    sendMessage(userMsg);
  };

  const handleRetry = () => {
    setHistory(prev => {
        const last = prev[prev.length - 1];
        return last?.role === 'model' ? prev.slice(0, -1) : prev;
    });
    sendMessage(lastUserMessage.current);
  };

  const handleClear = () => {
    setProblem('');
    setHistory([]);
    setStatus(Status.IDLE);
    chatRef.current = null;
    lastUserMessage.current = '';
  };

  const handleProblemChange = (newProblem: string) => {
    setProblem(newProblem);
    if(status === Status.ERROR) setStatus(Status.IDLE);
  };

  return (
    <div className="h-screen w-screen bg-gradient-to-tr from-[#FFF8E1] via-[#FFF3E0] to-[#E1F5FE] relative flex flex-col items-center overflow-hidden text-gray-800 selection:bg-yellow-100">

      {/* Background Sparkles Decorations */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none opacity-40">
        <div className="absolute top-[5%] left-[5%] text-2xl animate-float-slow">✨</div>
        <div className="absolute top-[12%] right-[10%] text-xl animate-float-medium">🌟</div>
        <div className="absolute bottom-[18%] left-[8%] text-3xl animate-float-slow">🌻</div>
        <div className="absolute bottom-[25%] right-[8%] text-2xl animate-float-medium">💖</div>
        <div className="absolute top-[40%] right-[15%] text-lg opacity-40 animate-pulse">☁️</div>
        <div className="absolute top-[60%] left-[12%] text-lg opacity-40 animate-pulse">🫧</div>
      </div>

      <div className="w-full max-w-lg mx-auto flex flex-col items-center h-full z-10 px-4 py-2 sm:py-4">

        {!isOnline && (
          <div className="fixed top-0.5 left-1/2 -translate-x-1/2 z-50 bg-orange-500 text-white px-3 py-0.5 rounded-full text-[7px] font-black shadow-lg animate-pulse tracking-widest uppercase">
            Offline
          </div>
        )}

        <div className="pb-1.5 flex-shrink-0">
          <Header />
        </div>

        <div className="w-full flex-1 flex flex-col min-h-0 overflow-hidden bg-white/75 backdrop-blur-3xl rounded-[2.5rem] border border-white shadow-[0_20px_60px_rgba(251,191,36,0.15)]">
          <div 
            ref={scrollRef}
            className="flex-1 overflow-y-auto p-4 sm:p-5 space-y-4 sm:space-y-6 scroll-smooth overscroll-contain custom-scrollbar"
          >
            {history.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center text-center px-4 select-none animate-fade-in">
                <div className="space-y-6">
                  <p className="text-2xl md:text-3xl font-black italic leading-tight max-w-xs mx-auto">
                    <span className="bg-clip-text text-transparent bg-gradient-to-r from-orange-600 via-pink-500 to-yellow-600 drop-shadow-sm">
                      "Every cloud has a silver Lining, Let me help you find yours"
                    </span>
                  </p>

                  <div className="space-y-4">
                    <p className="text-sm md:text-base text-gray-600 font-medium tracking-tight px-2">
                      I'm ELIX your Personal Companion for growth. 🌿<br/>
                      <span className="mt-2 block text-orange-600 font-bold italic">
                        In order to help you find your brightest self, please share a problem or a worry that's on your mind.
                      </span>
                    </p>
                    <div className="flex justify-center gap-3 text-xl opacity-60">🫧 🪐 🐚 🕊️</div>
                  </div>

                  <div className="pt-2">
                    <span className="px-4 py-1.5 bg-gradient-to-r from-yellow-100/60 to-orange-100/60 text-yellow-800 text-[9px] font-black uppercase tracking-[0.3em] rounded-full border border-yellow-200/50 shadow-sm">
                      Safe Space • Pure Heart • Silver Linings
                    </span>
                  </div>
                </div>
              </div>
            )}
            {history.map((msg, i) => {
              const isLastError = i === history.length - 1 && status === Status.ERROR && msg.role === 'model';
              return (
                <MessageBubble 
                  key={i} 
                  msg={msg} 
                  isError={isLastError} 
                  onRetry={isLastError ? handleRetry : undefined} 
                />
              );
            })}
            {status === Status.LOADING && (
               <div className="flex justify-start px-2">
                <div className="bg-yellow-50/95 backdrop-blur-sm w-16 h-8 rounded-full flex items-center justify-center space-x-1.5 border border-yellow-100 shadow-sm">
                  <div className="w-1.5 h-1.5 bg-yellow-500 rounded-full animate-bounce [animation-duration:0.6s]"></div>
                  <div className="w-1.5 h-1.5 bg-yellow-500 rounded-full animate-bounce [animation-delay:0.2s] [animation-duration:0.6s]"></div>
                  <div className="w-1.5 h-1.5 bg-yellow-500 rounded-full animate-bounce [animation-delay:0.4s] [animation-duration:0.6s]"></div>
                </div>
               </div>
            )}
          </div>

          <div className="p-4 sm:p-5 bg-white/60 border-t border-white/80 flex-shrink-0">
            <ProblemInput 
              problem={problem}
              onProblemChange={handleProblemChange}
              onSubmit={handleSubmit}
              isLoading={status === Status.LOADING}
            />
            {history.length > 0 && (
               <button 
                onClick={handleClear}
                className="mt-2 text-[8px] font-black text-gray-400 hover:text-orange-500 uppercase tracking-[0.3em] w-full text-center py-1 transition-all outline-none hover:scale-105 active:scale-95"
              >
                Start a New Chapter ✨
              </button>
            )}
          </div>
        </div>

        <footer className="text-center text-gray-400 text-[7px] mt-2 uppercase tracking-[0.5em] flex-shrink-0 select-none font-black z-10 opacity-70">
          ELIX COMPANION • YOUR HEART'S MIRROR • BRIGHTER SIDE
        </footer>
      </div>

      <style>{`
        .animate-fade-in {
          animation: fadeIn 0.8s cubic-bezier(0.23, 1, 0.32, 1) forwards;
        }
        .animate-float-slow {
          animation: float 9s ease-in-out infinite;
        }
        .animate-float-medium {
          animation: float 7s ease-in-out infinite;
        }
        .animate-bounce-subtle {
          animation: bounceSubtle 4s ease-in-out infinite;
        }
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(15px) scale(0.98); filter: blur(4px); }
          to { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
        }
        @keyframes float {
          0%, 100% { transform: translateY(0) translateX(0); }
          50% { transform: translateY(-12px) translateX(6px); }
        }
        @keyframes bounceSubtle {
          0%, 100% { transform: translateY(0); }
          50% { transform: translateY(-4px); }
        }

        .custom-scrollbar::-webkit-scrollbar {
          width: 7px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }
