          background-color: rgba(15, 23, 42, 0.75);
          border-radius: 10px;
          border: 2px solid transparent;
          background-clip: content-box;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background-color: rgba(15, 23, 42, 0.95);
        }
