          const newHistory = [...prev];
          const lastMsg = newHistory[newHistory.length - 1];
          if (lastMsg && lastMsg.role === 'model') {
            newHistory[newHistory.length - 1] = { ...lastMsg, text: fullText };
          }
          return newHistory;
        });
      }
    } catch (error: any) {
      console.error(`Attempt ${retryCount + 1} failed:`, error);

      if (retryCount < MAX_RETRIES && (error.message?.includes('fetch') || !navigator.onLine)) {
        const delay = Math.pow(2, retryCount) * 1000;
        setTimeout(() => sendMessage(messageText, retryCount + 1), delay);
        return;
      }

      setStatus(Status.ERROR);
      let errorText = "I'm so sorry, I hit a little snag. But I'm still right here for you! Let's try that again. ✨💖✨";
      if (error?.message?.includes("ELIX_MISSING_API_KEY")) {
        errorText = "I can't seem to find my API key sunshine! ☀️ Please check your environment variables so I can help you find those silver linings. ✨";
      }

      setHistory(prev => [...prev, { role: 'model', text: errorText }]);
    }
  }, []);

  const handleSubmit = () => {
    const userMsg = problem.trim();
    if (!userMsg) return;
    setHistory(prev => [...prev, { role: 'user', text: userMsg }]);
    setProblem('');
    sendMessage(userMsg);
  };

  const handleRetry = () => {
    setHistory(prev => {
        const last = prev[prev.length - 1];
        return last?.role === 'model' ? prev.slice(0, -1) : prev;
    });
    sendMessage(lastUserMessage.current);
  };

  const handleClear = () => {
    setProblem('');
    setHistory([]);
    setStatus(Status.IDLE);
    chatRef.current = null;
    lastUserMessage.current = '';
  };

  const handleProblemChange = (newProblem: string) => {
    setProblem(newProblem);
    if(status === Status.ERROR) setStatus(Status.IDLE);
  };

  return (
    <div className="h-screen w-screen bg-gradient-to-tr from-[#FFF8E1] via-[#FFF3E0] to-[#E1F5FE] relative flex flex-col items-center overflow-hidden text-gray-800 selection:bg-yellow-100">

      {/* Background Sparkles Decorations */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none opacity-40">
        <div className="absolute top-[5%] left-[5%] text-2xl animate-float-slow">✨</div>
        <div className="absolute top-[12%] right-[10%] text-xl animate-float-medium">🌟</div>
        <div className="absolute bottom-[18%] left-[8%] text-3xl animate-float-slow">🌻</div>
        <div className="absolute bottom-[25%] right-[8%] text-2xl animate-float-medium">💖</div>
        <div className="absolute top-[40%] right-[15%] text-lg opacity-40 animate-pulse">☁️</div>
        <div className="absolute top-[60%] left-[12%] text-lg opacity-40 animate-pulse">🫧</div>
      </div>

      <div className="w-full max-w-lg mx-auto flex flex-col items-center h-full z-10 px-4 py-2 sm:py-4">

        {!isOnline && (
          <div className="fixed top-0.5 left-1/2 -translate-x-1/2 z-50 bg-orange-500 text-white px-3 py-0.5 rounded-full text-[7px] font-black shadow-lg animate-pulse tracking-widest uppercase">
            Offline
          </div>
        )}

        <div className="pb-1.5 flex-shrink-0">
          <Header />
        </div>

        <div className="w-full flex-1 flex flex-col min-h-0 overflow-hidden bg-white/75 backdrop-blur-3xl rounded-[2.5rem] border border-white shadow-[0_20px_60px_rgba(251,191,36,0.15)]">
          <div 
            ref={scrollRef}
            className="flex-1 overflow-y-auto p-4 sm:p-5 space-y-4 sm:space-y-6 scroll-smooth overscroll-contain custom-scrollbar"
          >
            {history.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center text-center px-4 select-none animate-fade-in">
                <div className="space-y-6">
                  <p className="text-2xl md:text-3xl font-black italic leading-tight max-w-xs mx-auto">
                    <span className="bg-clip-text text-transparent bg-gradient-to-r from-orange-600 via-pink-500 to-yellow-600 drop-shadow-sm">
                      "Every cloud has a silver Lining, Let me help you find yours"
                    </span>
                  </p>

                  <div className="space-y-4">
                    <p className="text-sm md:text-base text-gray-600 font-medium tracking-tight px-2">
                      I'm ELIX your Personal Companion for growth. 🌿<br/>
                      <span className="mt-2 block text-orange-600 font-bold italic">
                        In order to help you find your brightest self, please share a problem or a worry that's on your mind.
                      </span>
                    </p>
                    <div className="flex justify-center gap-3 text-xl opacity-60">🫧 🪐 🐚 🕊️</div>
                  </div>

                  <div className="pt-2">
                    <span className="px-4 py-1.5 bg-gradient-to-r from-yellow-100/60 to-orange-100/60 text-yellow-800 text-[9px] font-black uppercase tracking-[0.3em] rounded-full border border-yellow-200/50 shadow-sm">
                      Safe Space • Pure Heart • Silver Linings
                    </span>
                  </div>
                </div>
              </div>
            )}
            {history.map((msg, i) => {
              const isLastError = i === history.length - 1 && status === Status.ERROR && msg.role === 'model';
              return (
                <MessageBubble 
                  key={i} 
                  msg={msg} 
                  isError={isLastError} 
                  onRetry={isLastError ? handleRetry : undefined} 
                />
              );
            })}
            {status === Status.LOADING && (
               <div className="flex justify-start px-2">
                <div className="bg-yellow-50/95 backdrop-blur-sm w-16 h-8 rounded-full flex items-center justify-center space-x-1.5 border border-yellow-100 shadow-sm">
                  <div className="w-1.5 h-1.5 bg-yellow-500 rounded-full animate-bounce [animation-duration:0.6s]"></div>
