import React, { useState, useCallback, useRef, useEffect } from 'react';
import { getGeminiService, OPTIMIST_INSTRUCTION } from './services/geminiService';
import { Status } from './types';
import Header from './components/Header';
import ProblemInput from './components/ProblemInput';

interface Message {
  role: 'user' | 'model';
  text: string;
}

const MessageBubble: React.FC<{ msg: Message; isError?: boolean; onRetry?: () => void }> = ({ msg, isError, onRetry }) => {
  const isUser = msg.role === 'user';

  return (
    <div className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-fade-in px-1`}>
      <div className={`max-w-[88%] p-3 sm:p-4 rounded-[1.25rem] shadow-md transition-all duration-500 hover:shadow-lg ${
        isUser 
          ? 'bg-gradient-to-br from-blue-500 to-indigo-600 text-white rounded-br-none shadow-blue-100/50' 
          : 'bg-white/90 backdrop-blur-md text-gray-800 rounded-bl-none border border-yellow-50 shadow-yellow-100/30'
      } ${isError ? 'border-red-100 bg-red-50' : ''}`}>
        <p className="leading-snug text-base sm:text-lg whitespace-pre-wrap font-medium tracking-tight">
          {msg.text}
        </p>

        {isError && onRetry && (
          <button 
            onClick={onRetry}
            className="mt-2 px-3 py-1 bg-red-500 text-white text-[9px] font-black rounded-full hover:bg-red-600 transition-all shadow-md active:scale-95 flex items-center gap-1.5"
          >
            <span>Try Again</span>
            <span>✨</span>
          </button>
        )}
      </div>
    </div>
  );
};

function App() {
  const [problem, setProblem] = useState<string>('');
  const [history, setHistory] = useState<Message[]>([]);
  const [status, setStatus] = useState<Status>(Status.IDLE);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const chatRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const lastUserMessage = useRef<string>('');

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      const { scrollHeight, clientHeight } = scrollRef.current;
      scrollRef.current.scrollTo({
        top: scrollHeight - clientHeight,
        behavior: 'smooth'
      });
    }
  }, [history, status]);

  const sendMessage = useCallback(async (messageText: string, retryCount = 0) => {
    if (!messageText.trim()) return;

    const MAX_RETRIES = 2;
    lastUserMessage.current = messageText.trim();
    setStatus(Status.LOADING);

    if (!navigator.onLine) {
        setStatus(Status.ERROR);
        setHistory(prev => [...prev, { role: 'model', text: "I can't seem to reach the clouds right now! ☁️ Please check your internet connection and try again. ✨💖" }]);
        return;
    }

    try {
