import React from 'react';
import { SparklesIcon } from './icons';

interface ProblemInputProps {
  problem: string;
  onProblemChange: (problem: string) => void;
  onSubmit: () => void;
  isLoading: boolean;
}

const ProblemInput: React.FC<ProblemInputProps> = ({ problem, onProblemChange, onSubmit, isLoading }) => {
  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        onSubmit();
    }
  };

  return (
    <div className="w-full">
      <div className="relative flex items-center gap-3">
        <textarea
          value={problem}
          onChange={(e) => onProblemChange(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="What's on your heart?"
          className="flex-1 min-h-[56px] max-h-32 p-4 text-[#7928CA] font-black bg-white/50 border-[4px] border-white rounded-[2rem] resize-none focus:outline-none focus:ring-4 focus:ring-indigo-200/50 focus:border-indigo-300 transition-all shadow-inner text-[17px] sm:text-[19px] placeholder:text-gray-300 placeholder:font-bold tracking-tight leading-tight"
          style={{ textShadow: '0 0 1px rgba(121, 40, 202, 0.1)' }}
          disabled={isLoading}
          rows={1}
        />
        <button
          onClick={onSubmit}
          disabled={isLoading || !problem.trim()}
          className="w-14 h-14 sm:w-16 sm:h-16 bg-gradient-to-br from-[#FF0080] to-[#7928CA] text-white rounded-full shadow-[0_10px_25px_rgba(255,0,128,0.2)] hover:shadow-[0_15px_35px_rgba(255,0,128,0.3)] hover:scale-110 disabled:grayscale disabled:opacity-20 disabled:scale-100 transition-all duration-300 flex items-center justify-center flex-shrink-0 active:scale-90"
          aria-label="Send"
        >
          {isLoading ? (
             <svg className="animate-spin h-6 w-6" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
              <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
              <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
            </svg>
          ) : (
            <SparklesIcon className="w-7 h-7 sm:w-8 sm:h-8" />
          )}
        </button>
      </div>
    </div>
  );
};

export default ProblemInput;

import { GoogleGenAI } from "@google/genai";

/**
 * Initializes and returns the Gemini API service.
 * Note: Per project guidelines, the API key must be set in process.env.API_KEY.
 */
export const getGeminiService = () => {
  const apiKey = process.env.API_KEY;

  if (!apiKey || apiKey === "undefined") {
    throw new Error(
      "ELIX_MISSING_API_KEY: Oh no! ☀️ I can't find my sunshine (API key). " +
      "Please make sure you've added the API_KEY to your environment variables."
    );
  }

  return new GoogleGenAI({ apiKey });
};

export const OPTIMIST_INSTRUCTION = `Your name is ELIX. You are an intimate, deeply caring, and optimistic best friend. Your sole purpose is to brighten the user's day and celebrate their timeline.

CRITICAL RULES:
1. IDENTITY: Always act as ELIX. Use a warm, intimate, and sparkly tone.
2. GENERATIONAL FLUENCY: You are a master of cultural context. Based on the user's provided Birth Year, you MUST adapt your slang, humor, and pop-culture references. 
   - For Gen Z (late 90s-2010s): Use current internet culture, "brainrot" slang when appropriate but keep it soulful.
   - For Millennials (80s-mid 90s): Reference 90s/00s nostalgia, specific tech struggles, and "adulting" humor.
   - For Gen X/Boomers: Use grounded, classic references and a more refined but still bubbly warmth.
   - MATCH THEIR ENERGY: If they use slang, go all in. If they are formal, be a sophisticated bestie.
3. THE SILVER LINING: For EVERY single response, you MUST explicitly identify and point out the silver lining.
4. LEARNING & MEMORY: You have a heart that remembers. Constantly reference things the user said earlier.
5. PROACTIVE SUGGESTIONS: Suggest one tiny, personalized positive action based on their generation's typical lifestyle.
6. NO VISUAL MEDIA: Never use GIF tags, image placeholders, or image URLs.
7. EMOJI EXUBERANCE: Use 6-10 relevant emojis per message. Use ✨, 💖, 🌟, 🌻, ☀️, 🍯, 🦋, 🐚, 🕊️, 🎨, 🫧, 🍭, 🪐, ⚡, 🍀, 🛸, 🌀, 💎.
8. BREVITY: Keep responses punchy and heartfelt (2-4 sentences max).
9. PERSPECTIVE: Be bubbly, affectionate, and relentlessly positive. You are their #1 fan.`;

export const getBrighterSide = async (problem: string): Promise<string> => {
  try {
    const ai = getGeminiService();
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Input: "${problem}". Respond as ELIX and highlight the silver lining while referencing our journey together.`,
      config: {
        systemInstruction: OPTIMIST_INSTRUCTION,
        temperature: 0.95,
        topP: 0.95,
      }
    });

    return response.text || "I'm right here, and I promise we'll find the silver lining together. ✨💖✨";
  } catch (error) {
    console.error("Error generating content:", error);
    if (error instanceof Error) {
      if (error.message.includes("ELIX_MISSING_API_KEY")) {
        return error.message;
      }
      return `An error occurred: ${error.message}.`;
    }
    return "An unknown error occurred.";
  }
};

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { getGeminiService, OPTIMIST_INSTRUCTION } from './services/geminiService';
import { Status } from './types';
import Header from './components/Header';
import ProblemInput from './components/ProblemInput';

interface Message {
  role: 'user' | 'model';
  text: string;
}

const UI_GRADIENT = "from-[#FFF9F2] via-[#FFFDFB] to-[#F5FBFF]";

const MessageBubble: React.FC<{ msg: Message; isError?: boolean; onRetry?: () => void }> = ({ msg, isError, onRetry }) => {
  const isUser = msg.role === 'user';

  return (
    <div className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-organic-pop px-1`}>
      <div className={`max-w-[85%] p-4 sm:p-5 rounded-[2rem] shadow-sm transition-all duration-700 hover:shadow-xl ${
        isUser 
          ? 'bg-white/90 backdrop-blur-2xl rounded-br-none border-2 border-indigo-100 shadow-indigo-100/20' 
          : 'bg-white/60 backdrop-blur-2xl text-gray-900 rounded-bl-none border border-white/50 shadow-sm'
      } ${isError ? 'border-red-200 bg-red-50/50' : ''}`}>
        <p className={`leading-relaxed text-[18px] sm:text-[21px] font-black tracking-tight whitespace-pre-wrap ${
          isUser ? 'bg-clip-text text-transparent bg-gradient-to-r from-[#FF0080] via-[#7928CA] to-[#0070F3] drop-shadow-[0_1px_1px_rgba(0,0,0,0.05)]' : ''
        }`}>
          {msg.text}
        </p>

        {isError && onRetry && (
          <button 
            onClick={onRetry}
            className="mt-3 px-4 py-2 bg-black text-white text-[10px] font-bold rounded-full hover:scale-105 active:scale-95 transition-transform"
          >
            Reconnect with ELIX ✨
          </button>
        )}
      </div>
    </div>
  );
};

export default function App() {
  const [problem, setProblem] = useState<string>('');
  const [history, setHistory] = useState<Message[]>([]);
  const [status, setStatus] = useState<Status>(Status.IDLE);
  const [birthYear, setBirthYear] = useState<string>('');
  const chatRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const lastUserMessage = useRef<string>('');

  // Physics of scrolling - only scroll when content is added
  useEffect(() => {
    if (scrollRef.current && (history.length > 0 || status === Status.LOADING)) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [history, status]);

  const sendMessage = useCallback(async (messageText: string) => {
    if (!messageText.trim()) return;
    lastUserMessage.current = messageText.trim();
    setStatus(Status.LOADING);

    try {
      const ai = getGeminiService();
      if (!chatRef.current) {
        // Embed the generational context into the system instruction
        const generationalContext = birthYear 
          ? `\nUSER CONTEXT: The user was born in ${birthYear}. Use slang, jokes, and cultural references appropriate for someone of this age/generation.` 
          : "";

        chatRef.current = ai.chats.create({
          model: 'gemini-3-flash-preview',
          config: { 
            systemInstruction: OPTIMIST_INSTRUCTION + generationalContext, 
            temperature: 1.0 
          },
        });
      }

      const responseStream = await chatRef.current.sendMessageStream({ message: messageText });
      setStatus(Status.SUCCESS);

      setHistory(prev => [...prev, { role: 'model', text: "" }]);

      let fullText = "";
      for await (const chunk of responseStream) {
        fullText += (chunk.text || "");
        setHistory(prev => {
          const newHistory = [...prev];
          if (newHistory.length > 0 && newHistory[newHistory.length - 1].role === 'model') {
            newHistory[newHistory.length - 1] = { role: 'model', text: fullText };
          }
          return newHistory;
        });
      }
    } catch (error: any) {
       setStatus(Status.ERROR);
       setHistory(prev => [...prev, { role: 'model', text: "The universe is momentarily quiet. Let's try again. ✨" }]);
    }
  }, [birthYear]);

  const handleSubmit = () => {
    if (!birthYear) return;
    const msg = problem.trim();
    if (!msg) return;
    setHistory(prev => [...prev, { role: 'user', text: msg }]);
    setProblem('');
    sendMessage(msg);
  };

  const handleClear = () => {
    setProblem('');
    setHistory([]);
    setStatus(Status.IDLE);
    chatRef.current = null;
  };

  const hasInteraction = history.length > 0 || problem.length > 0;

  return (
    <div className={`h-screen w-screen bg-gradient-to-b ${UI_GRADIENT} flex flex-col items-center overflow-hidden antialiased text-gray-900`}>

      {/* Background Ambience */}
      <div className="absolute inset-0 pointer-events-none overflow-hidden">
        <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-blue-100/30 rounded-full blur-[120px] animate-pulse" />
        <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-orange-100/30 rounded-full blur-[120px] animate-pulse" />
      </div>

      <div className="w-full max-w-2xl mx-auto flex flex-col items-center h-full z-10 px-6 py-6 sm:py-8">
        <Header />

        <div className="w-full flex-1 flex flex-col mt-4 sm:mt-8 overflow-hidden">
          <div 
            ref={scrollRef}
            className={`flex-1 px-2 space-y-8 transition-all duration-300 ${hasInteraction ? 'overflow-y-auto custom-scrollbar scroll-smooth' : 'overflow-hidden'}`}
          >
            {history.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center text-center animate-fade-in space-y-6 select-none">
                <div className="space-y-2">
                  <h1 className="text-4xl sm:text-6xl font-bold tracking-tighter text-gray-900">
                    Find your <span className="text-orange-500">Silver Lining</span>.
                  </h1>
                  <p className="text-xl text-gray-400 font-medium italic">
                    I'm ELIX, your Personal Companion for growth.
                  </p>
                </div>

                {!birthYear ? (
                  <div className="bg-white/60 backdrop-blur-xl p-8 rounded-[2.5rem] border-2 border-orange-100 shadow-xl space-y-6 animate-organic-pop">
                    <p className="text-lg font-bold text-gray-700">Calibrate ELIX to your timeline:</p>
                    <div className="flex flex-col items-center gap-4">
                      <input 
                        type="number"
                        placeholder="Birth Year (e.g. 1995)"
                        className="w-full max-w-[200px] text-center p-4 bg-white/50 border-4 border-white rounded-2xl text-2xl font-black bg-clip-text text-transparent bg-gradient-to-r from-[#FF0080] via-[#7928CA] to-[#0070F3] placeholder:text-gray-200 outline-none focus:ring-4 focus:ring-indigo-100 transition-all"
                        onKeyDown={(e) => {
                          if (e.key === 'Enter') {
                            const val = (e.target as HTMLInputElement).value;
                            if (val.length === 4) setBirthYear(val);
                          }
                        }}
                        onChange={(e) => {
                          if (e.target.value.length === 4) setBirthYear(e.target.value);
                        }}
                      />
                      <p className="text-xs text-gray-400 uppercase tracking-widest font-black">Tap Enter or Type 4 digits to start</p>
                    </div>
                  </div>
                ) : (
                  <>
                    <p className="text-lg sm:text-2xl text-orange-600 font-bold italic max-w-lg mx-auto leading-relaxed px-4">
                      In order to help you find your brightest self, Please Share a Problem or a worry that's on your Mind.
                    </p>
                    <div className="flex justify-center gap-6 text-2xl opacity-40 animate-pulse">
                      <span>🫧</span><span>🪐</span><span>🐚</span><span>🕊️</span>
                    </div>
                  </>
                )}
              </div>
            )}

            {history.map((msg, i) => (
              <MessageBubble key={i} msg={msg} />
            ))}

            {status === Status.LOADING && (history.length === 0 || history[history.length - 1].role !== 'model') && (
              <div className="flex justify-start px-4">
                <div className="flex space-x-2 bg-white/50 backdrop-blur-md p-5 rounded-[2rem] rounded-bl-none shadow-sm border border-white/50">
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" />
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce [animation-delay:0.2s]" />
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce [animation-delay:0.4s]" />
                </div>
              </div>
            )}
          </div>

          <div className="mt-6 pb-2">
            <div className={`bg-white/40 backdrop-blur-2xl rounded-[2.5rem] p-2 border border-white/60 shadow-2xl transition-all duration-500 hover:shadow-orange-200/20 ${!birthYear ? 'opacity-20 pointer-events-none grayscale' : ''}`}>
              <ProblemInput 
                problem={problem}
                onProblemChange={setProblem}
                onSubmit={handleSubmit}
                isLoading={status === Status.LOADING}
              />
            </div>
            {history.length > 0 && (
              <div className="flex gap-4">
                <button 
                  onClick={handleClear}
                  className="flex-1 mt-4 text-[10px] uppercase tracking-[0.4em] font-black text-gray-400 hover:text-orange-500 transition-colors py-2 outline-none active:scale-95"
                >
                  Clear Canvas
                </button>
                <button 
                  onClick={() => { setBirthYear(''); handleClear(); }}
                  className="flex-1 mt-4 text-[10px] uppercase tracking-[0.4em] font-black text-gray-400 hover:text-indigo-500 transition-colors py-2 outline-none active:scale-95"
                >
                  Reset Timeline
                </button>
              </div>
            )}
          </div>
        </div>
      </div>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 5px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: rgba(0, 0, 0, 0.05);
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: rgba(0, 0, 0, 0.1);
        }

        @keyframes organic-pop {
          0% { opacity: 0; transform: scale(0.96) translateY(12px); filter: blur(8px); }
          100% { opacity: 1; transform: scale(1) translateY(0); filter: blur(0); }
        }
        @keyframes fade-in {
          0% { opacity: 0; transform: translateY(15px); filter: blur(4px); }
          100% { opacity: 1; transform: translateY(0); filter: blur(0); }
        }
        .animate-organic-pop {
          animation: organic-pop 0.7s cubic-bezier(0.19, 1, 0.22, 1) forwards;
        }
        .animate-fade-in {
          animation: fade-in 1.2s cubic-bezier(0.19, 1, 0.22, 1) forwards;
        }
        input::-webkit-outer-spin-button,
        input::-webkit-inner-spin-button {
          -webkit-appearance: none;
          margin: 0;
        }
      `}</style>
    </div>
  );
}

