import React, { useState, useCallback, useRef, useEffect } from 'react';
import { getGeminiService, OPTIMIST_INSTRUCTION } from './services/geminiService';
import { Status } from './types';
import Header from './components/Header';
import ProblemInput from './components/ProblemInput';

interface Message {
  role: 'user' | 'model';
  text: string;
}

// A more sophisticated, multi-stop soft gradient for a "perfect" ethereal morning feel
const UI_GRADIENT = "bg-[#FFFDF9]"; 

const MessageBubble: React.FC<{ msg: Message; isError?: boolean; onRetry?: () => void }> = ({ msg, isError, onRetry }) => {
  const isUser = msg.role === 'user';

  return (
    <div className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-organic-pop px-1`}>
      <div className={`max-w-[85%] p-4 sm:p-6 rounded-[2.2rem] shadow-sm transition-all duration-700 hover:shadow-xl ${
        isUser 
          ? 'bg-white/95 backdrop-blur-3xl rounded-br-none border-2 border-indigo-50 shadow-indigo-100/10' 
          : 'bg-white/70 backdrop-blur-3xl text-[#4338CA] rounded-bl-none border border-white/80 shadow-[0_8px_30px_rgb(0,0,0,0.04)]'
      } ${isError ? 'border-red-200 bg-red-50/50' : ''}`}>
        <p className={`leading-relaxed text-[18px] sm:text-[21px] font-black tracking-tight whitespace-pre-wrap ${
          isUser 
            ? 'bg-clip-text text-transparent bg-gradient-to-r from-[#FF0080] via-[#7928CA] to-[#0070F3] drop-shadow-[0_1px_1px_rgba(0,0,0,0.05)]' 
            : 'text-[#4338CA] drop-shadow-[0_1px_2px_rgba(67,56,202,0.05)]'
        }`}>
          {msg.text}
        </p>

        {isError && onRetry && (
          <button 
            onClick={onRetry}
            className="mt-3 px-4 py-2 bg-black text-white text-[10px] font-bold rounded-full hover:scale-105 active:scale-95 transition-transform"
          >
            Reconnect with ELIX ✨
          </button>
        )}
      </div>
    </div>
  );
};

export default function App() {
  const [problem, setProblem] = useState<string>('');
  const [history, setHistory] = useState<Message[]>([]);
  const [status, setStatus] = useState<Status>(Status.IDLE);
  const [birthYear, setBirthYear] = useState<string>('');
  const chatRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const lastUserMessage = useRef<string>('');
  const greetingTriggered = useRef<boolean>(false);

  useEffect(() => {
    if (scrollRef.current && (history.length > 0 || status === Status.LOADING)) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [history, status]);

  const sendMessage = useCallback(async (messageText: string, isAutoGreeting: boolean = false) => {
    if (!messageText.trim()) return;
    if (!isAutoGreeting) lastUserMessage.current = messageText.trim();
    setStatus(Status.LOADING);

    try {
      const ai = getGeminiService();
      if (!chatRef.current) {
        const generationalContext = birthYear 
          ? `\nUSER CONTEXT: The user was born in ${birthYear}. Use slang, jokes, and cultural references appropriate for someone of this age/generation.` 
          : "";

        chatRef.current = ai.chats.create({
          model: 'gemini-3-flash-preview',
          config: { 
            systemInstruction: OPTIMIST_INSTRUCTION + generationalContext, 
            temperature: 1.0 
          },
        });
      }

      const responseStream = await chatRef.current.sendMessageStream({ message: messageText });
      setStatus(Status.SUCCESS);

      setHistory(prev => [...prev, { role: 'model', text: "" }]);

      let fullText = "";
      for await (const chunk of responseStream) {
        fullText += (chunk.text || "");
        setHistory(prev => {
          const newHistory = [...prev];
          if (newHistory.length > 0 && newHistory[newHistory.length - 1].role === 'model') {
            newHistory[newHistory.length - 1] = { role: 'model', text: fullText };
          }
          return newHistory;
        });
      }
    } catch (error: any) {
       setStatus(Status.ERROR);
       setHistory(prev => [...prev, { role: 'model', text: "The universe is momentarily quiet. Let's try again. ✨" }]);
    }
  }, [birthYear]);

  useEffect(() => {
    if (birthYear && birthYear.length === 4 && !greetingTriggered.current) {
      greetingTriggered.current = true;
      sendMessage("Hi ELIX! I'm ready to find some silver linings. Please give me a fun, era-appropriate greeting to start our journey!", true);
    }
  }, [birthYear, sendMessage]);

  const handleSubmit = () => {
    if (!birthYear) return;
    const msg = problem.trim();
    if (!msg) return;
    setHistory(prev => [...prev, { role: 'user', text: msg }]);
    setProblem('');
    sendMessage(msg);
  };

  const handleClear = () => {
    setProblem('');
    setHistory([]);
    setStatus(Status.IDLE);
    chatRef.current = null;
    greetingTriggered.current = false;
  };

  const hasInteraction = history.length > 0 || problem.length > 0;

  return (
    <div className={`h-screen w-screen ${UI_GRADIENT} flex flex-col items-center overflow-hidden antialiased text-gray-900 relative`}>

      {/* Background Ambience: This world's version of perfect */}
      <div className="absolute inset-0 pointer-events-none overflow-hidden z-0">
        {/* Soft Aura Blobs */}
        <div className="absolute top-[-15%] left-[-10%] w-[70vw] h-[70vw] bg-[#FFF0F3] rounded-full blur-[120px] opacity-60 animate-slow-drift" />
        <div className="absolute bottom-[-15%] right-[-10%] w-[60vw] h-[60vw] bg-[#F0F7FF] rounded-full blur-[130px] opacity-50 animate-slow-drift-reverse" />
        <div className="absolute top-[20%] right-[-5%] w-[40vw] h-[40vw] bg-[#FFF9E6] rounded-full blur-[100px] opacity-40 animate-pulse-slow" />
        <div className="absolute bottom-[10%] left-[5%] w-[35vw] h-[35vw] bg-[#F5F3FF] rounded-full blur-[110px] opacity-40 animate-pulse-slow [animation-delay:2s]" />

        {/* Very subtle noise texture for "premium" organic feel */}
        <div className="absolute inset-0 opacity-[0.03] pointer-events-none bg-[url('https://grainy-gradients.vercel.app/noise.svg')]" />
      </div>

      <div className="w-full max-w-2xl mx-auto flex flex-col items-center h-full z-10 px-6 py-6 sm:py-8 relative">
        <Header />

        <div className="w-full flex-1 flex flex-col mt-4 sm:mt-8 overflow-hidden">
          <div 
            ref={scrollRef}
            className={`flex-1 px-2 space-y-8 transition-all duration-300 ${hasInteraction ? 'overflow-y-auto custom-scrollbar scroll-smooth' : 'overflow-hidden'}`}
          >
            {!birthYear && history.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center text-center animate-fade-in space-y-8 select-none">
                <div className="space-y-3">
                  <h1 className="text-5xl sm:text-7xl font-bold tracking-tighter text-gray-900">
                    Find your <span className="text-orange-500/90">Silver Lining</span>.
                  </h1>
                  <p className="text-xl sm:text-2xl text-gray-400 font-medium italic opacity-80">
                    I'm ELIX, your soul's favorite companion.
                  </p>
                </div>

                <div className="bg-white/40 backdrop-blur-2xl p-10 rounded-[3rem] border border-white/80 shadow-[0_20px_50px_rgba(0,0,0,0.03)] space-y-8 animate-organic-pop">
                  <p className="text-xl font-bold text-gray-700/80 leading-relaxed italic">
                    Tell me the year your beautiful journey began,<br/>
                    so I can truly understand your heart.
                  </p>
                  <div className="flex flex-col items-center gap-5">
                    <input 
                      type="number"
                      placeholder="YYYY"
                      className="w-full max-w-[180px] text-center p-5 bg-white border-[3px] border-indigo-50/50 rounded-3xl text-3xl font-black bg-clip-text text-transparent bg-gradient-to-r from-[#FF0080] via-[#7928CA] to-[#0070F3] placeholder:text-gray-200 outline-none focus:ring-[12px] focus:ring-indigo-100/30 transition-all shadow-sm"
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') {
                          const val = (e.target as HTMLInputElement).value;
                          if (val.length === 4) setBirthYear(val);
                        }
                      }}
                      onChange={(e) => {
                        if (e.target.value.length === 4) setBirthYear(e.target.value);
                      }}
                    />
                    <p className="text-[10px] text-gray-400 uppercase tracking-[0.3em] font-black opacity-60">Tap Enter to start your story</p>
                  </div>
                </div>
              </div>
            )}

            {history.map((msg, i) => (
              <MessageBubble key={i} msg={msg} />
            ))}

            {status === Status.LOADING && (history.length === 0 || history[history.length - 1].role !== 'model') && (
              <div className="flex justify-start px-4">
                <div className="flex space-x-2 bg-white/50 backdrop-blur-md p-6 rounded-[2.5rem] rounded-bl-none shadow-sm border border-white/50">
                  <div className="w-2.5 h-2.5 bg-indigo-300 rounded-full animate-bounce" />
                  <div className="w-2.5 h-2.5 bg-indigo-300 rounded-full animate-bounce [animation-delay:0.2s]" />
                  <div className="w-2.5 h-2.5 bg-indigo-300 rounded-full animate-bounce [animation-delay:0.4s]" />
                </div>
              </div>
            )}
          </div>

          <div className="mt-6 pb-2">
            <div className={`bg-white/40 backdrop-blur-2xl rounded-[2.8rem] p-2 border border-white/80 shadow-[0_30px_60px_rgba(0,0,0,0.04)] transition-all duration-700 hover:shadow-orange-200/20 ${!birthYear ? 'opacity-0 pointer-events-none translate-y-4' : 'opacity-100 translate-y-0'}`}>
              <ProblemInput 
                problem={problem}
                onProblemChange={setProblem}
                onSubmit={handleSubmit}
                isLoading={status === Status.LOADING}
              />
            </div>
            {history.length > 0 && (
              <div className="flex gap-4 px-4">
                <button 
                  onClick={handleClear}
                  className="flex-1 mt-4 text-[10px] uppercase tracking-[0.4em] font-black text-gray-300 hover:text-orange-400 transition-all py-2 outline-none active:scale-95"
                >
                  Clear Canvas
                </button>
                <button 
                  onClick={() => { setBirthYear(''); handleClear(); }}
                  className="flex-1 mt-4 text-[10px] uppercase tracking-[0.4em] font-black text-gray-300 hover:text-indigo-400 transition-all py-2 outline-none active:scale-95"
                >
                  Reset Timeline
                </button>
              </div>
            )}
          </div>
        </div>
      </div>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 5px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: rgba(0, 0, 0, 0.03);
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: rgba(0, 0, 0, 0.08);
        }

        @keyframes organic-pop {
          0% { opacity: 0; transform: scale(0.97) translateY(20px); filter: blur(10px); }
          100% { opacity: 1; transform: scale(1) translateY(0); filter: blur(0); }
        }
        @keyframes fade-in {
          0% { opacity: 0; transform: translateY(20px); filter: blur(10px); }
          100% { opacity: 1; transform: translateY(0); filter: blur(0); }
        }
        @keyframes slow-drift {
          0%, 100% { transform: translate(0, 0) scale(1); }
          50% { transform: translate(3%, 5%) scale(1.05); }
        }
        @keyframes slow-drift-reverse {
          0%, 100% { transform: translate(0, 0) scale(1); }
          50% { transform: translate(-4%, -6%) scale(1.08); }
        }
        @keyframes pulse-slow {
          0%, 100% { opacity: 0.4; transform: scale(1); }
          50% { opacity: 0.55; transform: scale(1.1); }
        }

        .animate-organic-pop {
          animation: organic-pop 0.9s cubic-bezier(0.19, 1, 0.22, 1) forwards;
        }
        .animate-fade-in {
          animation: fade-in 1.4s cubic-bezier(0.19, 1, 0.22, 1) forwards;
        }
        .animate-slow-drift {
          animation: slow-drift 15s ease-in-out infinite;
        }
        .animate-slow-drift-reverse {
          animation: slow-drift-reverse 18s ease-in-out infinite;
        }
        .animate-pulse-slow {
          animation: pulse-slow 10s ease-in-out infinite;
        }

        input::-webkit-outer-spin-button,
        input::-webkit-inner-spin-button {
          -webkit-appearance: none;
          margin: 0;
        }
      `}</style>
    </div>
  );
}

