import React, { useState, useCallback, useRef, useEffect } from 'react';
import { getGeminiService, OPTIMIST_INSTRUCTION } from './services/geminiService';
import { Status } from './types';
import Header from './components/Header';
import ProblemInput from './components/ProblemInput';

interface Message {
  role: 'user' | 'model';
  text: string;
}

const UI_GRADIENT = "bg-[#FFFEFB]"; 

// --- UPDATED MESSAGE BUBBLE WITH SHARE OPTION ---
const MessageBubble: React.FC<{ msg: Message; isError?: boolean; onRetry?: () => void }> = ({ msg, isError, onRetry }) => {
  const isUser = msg.role === 'user';

  const handleCopy = () => {
    navigator.clipboard.writeText(msg.text);
    // You could add a 'Copied!' toast here
  };

  return (
    <div className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-organic-pop px-1 group relative`}>
      <div className={`max-w-[85%] p-4 sm:p-6 rounded-[2.5rem] shadow-sm transition-all duration-1000 hover:shadow-xl ${
        isUser 
          ? 'bg-white/95 backdrop-blur-3xl rounded-br-none border-2 border-indigo-50 shadow-indigo-100/10' 
          : 'bg-white/70 backdrop-blur-3xl text-[#4338CA] rounded-bl-none border border-white/80'
      } ${isError ? 'border-red-200 bg-red-50/50' : ''}`}>
        <p className={`leading-relaxed text-[18px] sm:text-[21px] font-black tracking-tight whitespace-pre-wrap ${
          isUser 
            ? 'bg-clip-text text-transparent bg-gradient-to-r from-[#FF0080] via-[#7928CA] to-[#0070F3]' 
            : 'text-[#4338CA]'
        }`}>
          {msg.text}
        </p>

        {/* Share Button (Visible on Hover/Tap) */}
        {!isUser && msg.text && (
          <button 
            onClick={handleCopy}
            className="absolute -right-8 top-1/2 -translate-y-1/2 opacity-0 group-hover:opacity-100 transition-opacity p-2 text-gray-400 hover:text-indigo-500"
            title="Share Wisdom"
          >
            <span className="text-xs font-black">COPY</span>
          </button>
        )}

        {isError && onRetry && (
          <button 
            onClick={onRetry}
            className="mt-3 px-4 py-2 bg-black text-white text-[10px] font-bold rounded-full"
          >
            Reconnect with ELIX ✨
          </button>
        )}
      </div>
    </div>
  );
};

export default function App() {
  const [problem, setProblem] = useState<string>('');
  const [history, setHistory] = useState<Message[]>([]);
  const [status, setStatus] = useState<Status>(Status.IDLE);
  const [birthYear, setBirthYear] = useState<string>('');
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const chatRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const greetingTriggered = useRef<boolean>(false);

  // --- BURGER MENU ACTIONS ---
  const saveHistory = () => {
    const chatContent = history.map(m => `${m.role.toUpperCase()}: ${m.text}`).join('\n\n');
    const blob = new Blob([chatContent], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `ELIX-Session-${new Date().toLocaleDateString()}.txt`;
    a.click();
    setIsMenuOpen(false);
  };

  const refreshAge = () => {
    setBirthYear('');
    greetingTriggered.current = false;
    setIsMenuOpen(false);
  };

  // Logic for Gemini remains same as your snippet...
  const sendMessage = useCallback(async (messageText: string, isAutoGreeting: boolean = false) => {
    if (!messageText.trim()) return;
    setStatus(Status.LOADING);
    try {
      const ai = getGeminiService();
      if (!chatRef.current) {
        const generationalContext = birthYear ? `\nUSER CONTEXT: The user was born in ${birthYear}.` : "";
        chatRef.current = ai.chats.create({
          model: 'gemini-3-flash-preview',
          config: { systemInstruction: OPTIMIST_INSTRUCTION + generationalContext, temperature: 1.0 },
        });
      }
      const responseStream = await chatRef.current.sendMessageStream({ message: messageText });
      setStatus(Status.SUCCESS);
      setHistory(prev => [...prev, { role: 'model', text: "" }]);
      let fullText = "";
      for await (const chunk of responseStream) {
        fullText += (chunk.text || "");
        setHistory(prev => {
          const newHistory = [...prev];
          if (newHistory.length > 0) newHistory[newHistory.length - 1].text = fullText;
          return newHistory;
        });
      }
    } catch (e) { setStatus(Status.ERROR); }
  }, [birthYear]);

  useEffect(() => {
    if (birthYear && birthYear.length === 4 && !greetingTriggered.current) {
      greetingTriggered.current = true;
      sendMessage("Hi ELIX! I'm ready.", true);
    }
  }, [birthYear, sendMessage]);

  const handleSubmit = () => {
    if (!birthYear || !problem.trim()) return;
    setHistory(prev => [...prev, { role: 'user', text: problem.trim() }]);
    sendMessage(problem.trim());
    setProblem('');
  };

  return (
    <div className={`h-screen w-screen ${UI_GRADIENT} flex flex-col items-center overflow-hidden antialiased text-gray-900 relative`}>

      {/* BURGER MENU TRIGGER */}
      <button 
        onClick={() => setIsMenuOpen(!isMenuOpen)}
        className="fixed top-6 left-6 z-[60] p-3 bg-white/50 backdrop-blur-xl rounded-full border border-gray-100 shadow-sm active:scale-90 transition-all"
      >
        <div className="w-5 h-4 flex flex-col justify-between">
          <span className={`h-0.5 bg-gray-900 rounded-full transition-all ${isMenuOpen ? 'rotate-45 translate-y-1.5' : ''}`} />
          <span className={`h-0.5 bg-gray-900 rounded-full transition-all ${isMenuOpen ? 'opacity-0' : ''}`} />
          <span className={`h-0.5 bg-gray-900 rounded-full transition-all ${isMenuOpen ? '-rotate-45 -translate-y-2' : ''}`} />
        </div>
      </button>

      {/* SLIDE-OUT MENU PANEL */}
      <div className={`fixed inset-0 z-[55] transition-all duration-700 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div 
          className={`absolute inset-0 bg-black/5 backdrop-blur-md transition-opacity duration-700 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} 
          onClick={() => setIsMenuOpen(false)}
        />
        <div className={`absolute left-0 top-0 bottom-0 w-72 bg-white/95 backdrop-blur-3xl shadow-2xl p-8 flex flex-col transition-transform duration-700 ease-in-out ${isMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
          <div className="mt-16 space-y-8">
            <h2 className="text-xs font-black tracking-[0.4em] text-gray-300 uppercase">Command Center</h2>
            <nav className="flex flex-col gap-6">
              <button onClick={saveHistory} className="text-left text-lg font-bold text-gray-800 hover:text-indigo-500 transition-colors">📁 Save This Journey</button>
              <button onClick={refreshAge} className="text-left text-lg font-bold text-gray-800 hover:text-indigo-500 transition-colors">⏳ Update My Age</button>
              <button onClick={() => { setHistory([]); setIsMenuOpen(false); }} className="text-left text-lg font-bold text-gray-800 hover:text-orange-500 transition-colors">✨ New Chapter</button>
            </nav>
          </div>
          <div className="mt-auto">
             <p className="text-[10px] font-black text-gray-300 tracking-widest uppercase">ELIX v3.0 • PROUDLY ORGANIC</p>
          </div>
        </div>
      </div>

      {/* Main Chat Content (Same structure as your previous code) */}
      <div className="w-full max-w-2xl mx-auto flex flex-col items-center h-full z-10 px-6 py-8">
        <Header />
        <div className="flex-1 w-full overflow-hidden mt-8">
           <div ref={scrollRef} className="h-full overflow-y-auto custom-scrollbar px-2 space-y-10">
              {/* Birthyear Input or History Mapping... */}
              {!birthYear && (
                <div className="h-full flex flex-col items-center justify-center animate-fade-in">
                   <h1 className="text-4xl font-black mb-8">What year did you begin?</h1>
                   <input 
                     className="bg-transparent text-6xl font-black text-center outline-none border-b-4 border-indigo-100 focus:border-indigo-500"
                     maxLength={4}
                     placeholder="YYYY"
                     onChange={(e) => e.target.value.length === 4 && setBirthYear(e.target.value)}
                   />
                </div>
              )}
              {history.map((msg, i) => <MessageBubble key={i} msg={msg} />)}
           </div>
        </div>

        {/* Input Area... */}
        {birthYear && (
          <div className="w-full mt-6 bg-white/50 backdrop-blur-2xl rounded-[2.5rem] p-2 border border-white">
            <ProblemInput 
              problem={problem} 
              onProblemChange={setProblem} 
              onSubmit={handleSubmit} 
              isLoading={status === Status.LOADING} 
            />
          </div>
        )}
      </div>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { display: none; }
        @keyframes organic-pop {
          0% { opacity: 0; transform: translateY(20px); }
          100% { opacity: 1; transform: translateY(0); }
        }
        .animate-organic-pop { animation: organic-pop 0.6s ease-out forwards; }
      `}</style>
    </div>
  );
}

