          >
            <span>{copied ? 'Wisdom Captured' : 'Copy Wisdom'}</span>
            <span className="text-sm">✨</span>
          </button>
        )}

        {isError && onRetry && (
          <button 
            onClick={onRetry}
            className="mt-4 px-6 py-3 bg-gray-900 text-white text-[11px] font-black uppercase tracking-widest rounded-full hover:bg-black transition-all active:scale-95 shadow-lg"
          >
