        <div className="absolute top-[-20%] left-[-15%] w-[100vw] h-[100vw] bg-[#FFF2F5] rounded-full blur-[140px] opacity-80 animate-slow-drift" />
        <div className="absolute bottom-[-15%] right-[-10%] w-[90vw] h-[90vw] bg-[#F3F9FF] rounded-full blur-[150px] opacity-70 animate-slow-drift-reverse" />
        <div className="absolute top-[15%] right-[-10%] w-[60vw] h-[60vw] bg-[#FFF9E0] rounded-full blur-[120px] opacity-60 animate-pulse-slow" />
        <div className="absolute bottom-[20%] left-[5%] w-[55vw] h-[55vw] bg-[#F7F2FF] rounded-full blur-[130px] opacity-60 animate-pulse-slow [animation-delay:3s]" />

