        {/* Fine Grain Texture */}
        <div className="absolute inset-0 opacity-[0.04] pointer-events-none mix-blend-overlay bg-[url('https://grainy-gradients.vercel.app/noise.svg')]" />
      </div>

      {/* BURGER MENU TRIGGER */}
      <button 
        onClick={() => setIsMenuOpen(!isMenuOpen)}
        className="fixed top-8 left-8 z-[110] p-4 bg-white/40 backdrop-blur-3xl rounded-2xl border border-white/50 shadow-[0_8px_30px_rgba(0,0,0,0.04)] active:scale-90 transition-all hover:bg-white/60 group"
