          <span className={`h-0.5 bg-gray-900 rounded-full transition-all duration-500 ${isMenuOpen ? 'w-0 opacity-0' : 'w-6'}`} />
          <span className={`h-0.5 bg-gray-900 rounded-full transition-all duration-500 ${isMenuOpen ? 'w-6 -rotate-45 -translate-y-2.5' : 'w-4 group-hover:w-6'}`} />
        </div>
      </button>

