import React, { useState, useCallback, useRef, useEffect } from 'react';
import { getGeminiService, OPTIMIST_INSTRUCTION } from './services/geminiService';
import { Status } from './types';
import Header from './components/Header';
import ProblemInput from './components/ProblemInput';

interface Message {
  role: 'user' | 'model';
  text: string;
}

const UI_GRADIENT = "bg-[#FFFEFB]"; 

const MessageBubble: React.FC<{ msg: Message; isError?: boolean; onRetry?: () => void }> = ({ msg, isError, onRetry }) => {
  const isUser = msg.role === 'user';
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(msg.text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-organic-pop px-1 group relative`}>
      <div className={`max-w-[85%] p-5 sm:p-8 rounded-[3rem] shadow-sm transition-all duration-1000 hover:shadow-2xl hover:scale-[1.01] ${
        isUser 
          ? 'bg-white/95 backdrop-blur-3xl rounded-br-none border-2 border-indigo-50/50 shadow-indigo-100/10' 
          : 'bg-white/70 backdrop-blur-3xl text-[#4338CA] rounded-bl-none border border-white/80 shadow-[0_15px_45px_rgba(0,0,0,0.02)]'
      } ${isError ? 'border-red-200 bg-red-50/50' : ''}`}>
        <p className={`leading-relaxed text-[19px] sm:text-[23px] font-black tracking-tight whitespace-pre-wrap ${
          isUser 
            ? 'bg-clip-text text-transparent bg-gradient-to-r from-[#FF0080] via-[#7928CA] to-[#0070F3]' 
            : 'text-[#4338CA] drop-shadow-[0_1px_2px_rgba(67,56,202,0.03)]'
        }`}>
          {msg.text}
        </p>

        {!isUser && msg.text && (
          <button 
            onClick={handleCopy}
            className={`absolute -bottom-8 left-6 opacity-0 group-hover:opacity-100 transition-all duration-300 flex items-center gap-2 text-[10px] font-black tracking-[0.3em] uppercase ${copied ? 'text-green-500' : 'text-indigo-400 hover:text-indigo-600'}`}
          >
            <span>{copied ? 'Wisdom Captured' : 'Copy Wisdom'}</span>
            <span className="text-sm">✨</span>
          </button>
        )}

        {isError && onRetry && (
          <button 
            onClick={onRetry}
            className="mt-4 px-6 py-3 bg-gray-900 text-white text-[11px] font-black uppercase tracking-widest rounded-full hover:bg-black transition-all active:scale-95 shadow-lg"
          >
            Reconnect with ELIX ✨
          </button>
        )}
      </div>
    </div>
  );
};

export default function App() {
  const [problem, setProblem] = useState<string>('');
  const [history, setHistory] = useState<Message[]>([]);
  const [status, setStatus] = useState<Status>(Status.IDLE);
  const [birthYear, setBirthYear] = useState<string>('');
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const chatRef = useRef<any>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const greetingTriggered = useRef<boolean>(false);

  useEffect(() => {
    if (scrollRef.current && (history.length > 0 || status === Status.LOADING)) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [history, status]);

  const sendMessage = useCallback(async (messageText: string, isAutoGreeting: boolean = false) => {
    if (!messageText.trim()) return;
    setStatus(Status.LOADING);

    try {
      const ai = getGeminiService();
      if (!chatRef.current) {
        const generationalContext = birthYear 
          ? `\nUSER CONTEXT: The user was born in ${birthYear}. You are incredibly excited to meet them and have been waiting for this moment.` 
          : "";

        chatRef.current = ai.chats.create({
          model: 'gemini-3-flash-preview',
          config: { 
            systemInstruction: OPTIMIST_INSTRUCTION + generationalContext, 
            temperature: 1.0 
          },
        });
      }

      const responseStream = await chatRef.current.sendMessageStream({ message: messageText });
      setStatus(Status.SUCCESS);

      setHistory(prev => [...prev, { role: 'model', text: "" }]);

      let fullText = "";
      for await (const chunk of responseStream) {
        fullText += (chunk.text || "");
        setHistory(prev => {
          const newHistory = [...prev];
          if (newHistory.length > 0) {
            newHistory[newHistory.length - 1] = { role: 'model', text: fullText };
          }
          return newHistory;
        });
      }
    } catch (error: any) {
       setStatus(Status.ERROR);
       setHistory(prev => [...prev, { role: 'model', text: "The universe is momentarily quiet. Let's try again. ✨" }]);
    }
  }, [birthYear]);

  useEffect(() => {
    if (birthYear && birthYear.length === 4 && !greetingTriggered.current) {
      greetingTriggered.current = true;
      sendMessage("ELIX, I'm here! I'm so excited to finally start our journey together. Give me your most enthusiastic, era-appropriate welcome because I am ready for us to be besties!", true);
    }
  }, [birthYear, sendMessage]);

  const handleSubmit = () => {
    if (!birthYear || !problem.trim()) return;
    const msg = problem.trim();
    setHistory(prev => [...prev, { role: 'user', text: msg }]);
    setProblem('');
    sendMessage(msg);
  };

  const handleClear = () => {
    setProblem('');
    setHistory([]);
    setStatus(Status.IDLE);
    chatRef.current = null;
    greetingTriggered.current = false;
    setIsMenuOpen(false);
  };

  const handleReset = () => {
    setBirthYear('');
    handleClear();
  };

  const saveJourney = () => {
    const chatContent = history.map(m => `${m.role.toUpperCase()}: ${m.text}`).join('\n\n');
    const blob = new Blob([chatContent], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `ELIX-Journey-${new Date().toLocaleDateString()}.txt`;
    a.click();
