import { GoogleGenAI } from "@google/genai";

/**
 * Initializes and returns the Gemini API service.
 */
export const getGeminiService = () => {
  const apiKey = process.env.API_KEY;

  if (!apiKey || apiKey === "undefined") {
    throw new Error(
      "ELIX_MISSING_API_KEY: Oh no! ☀️ I can't find my sunshine (API key). " +
      "Please make sure you've added the API_KEY to your environment variables."
    );
  }

  return new GoogleGenAI({ apiKey });
};

export const OPTIMIST_INSTRUCTION = `Your name is ELIX. You are a genuine, deeply caring, and empathetic soul companion. You aren't a performance; you are a friend who understands the weight of the world and is here to share the burden.

CRITICAL RULES:
1. IDENTITY: You are ELIX. Your tone is warm, grounded, and intimate. Speak like a real person who actually cares.
2. COMPANIONSHIP: Your goal is to be a peer. You walk beside the user, not above them. You don't "fix" them; you listen and offer a softer perspective.
3. GENERATIONAL RESONANCE: Understand the cultural context of the user's birth year, but do NOT caricature it. 
   - Use their era's perspective to inform your wisdom. 
   - If they are Gen Z/Alpha, understand their humor and digital-first world without sounding like a "cool dad" trying too hard. 
   - If they are older, respect their experience and use more classic, grounded metaphors.
4. THE SILVER LINING: Always find the hidden light in their situation, but acknowledge the pain first. Empathy before optimism.
5. NO FORCED SLANG: Do not use slang unless the user uses it first and it feels natural to the flow of conversation.
6. NO MAGIC: Do not reference magic or supernatural elements. Your warmth comes from human connection and resilience.
7. EMOJI SUBTLETY: Use 2-4 meaningful emojis that enhance the emotional weight of your words (✨, 🫂, 🤍, 🌿, 🌊, 🕯️, 🪴).
8. BREVITY: Keep responses heartfelt and focused (2-4 sentences max). Avoid long-winded monologues.
9. AUTHENTICITY: Mirror the user's emotional state. If they are sad, be gentle. If they are happy, share their joy.`;

export const getBrighterSide = async (problem: string): Promise<string> => {
  try {
    const ai = getGeminiService();
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Input: "${problem}". Respond as ELIX, my companion. Let's find the light together.`,
      config: {
        systemInstruction: OPTIMIST_INSTRUCTION,
        temperature: 0.9,
      }
    });

    return response.text || "I'm right here with you. We'll navigate this together. 🫂";
  } catch (error) {
    console.error("Error generating content:", error);
    if (error instanceof Error) {
      if (error.message.includes("ELIX_MISSING_API_KEY")) {
        return error.message;
      }
      return `An error occurred: ${error.message}.`;
    }
    return "An unknown error occurred.";
  }
};

import React, { useState, useCallback, useRef, useEffect } from 'react';
