import React, { useState, useCallback, useRef, useEffect } from 'react';
import { getGeminiService, OPTIMIST_INSTRUCTION } from './services/geminiService';
import { Status } from './types';
import Header from './components/Header';
import ProblemInput from './components/ProblemInput';

interface Message {
  role: 'user' | 'model';
  text: string;
}

const UI_GRADIENT = "bg-[#FFFEFB]"; 

const MessageBubble: React.FC<{ msg: Message; isError?: boolean; onRetry?: () => void }> = ({ msg, isError, onRetry }) => {
  const isUser = msg.role === 'user';
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(msg.text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-organic-pop px-1 group relative`}>
      <div className={`max-w-[85%] p-5 sm:p-8 rounded-[3rem] shadow-sm transition-all duration-1000 hover:shadow-2xl hover:scale-[1.01] ${
        isUser 
          ? 'bg-white/95 backdrop-blur-3xl rounded-br-none border-2 border-indigo-50/50 shadow-indigo-100/10' 
          : 'bg-white/70 backdrop-blur-3xl text-[#4338CA] rounded-bl-none border border-white/80 shadow-[0_15px_45px_rgba(0,0,0,0.02)]'
      } ${isError ? 'border-red-200 bg-red-50/50' : ''}`}>
        <p className={`leading-relaxed text-[19px] sm:text-[23px] font-black tracking-tight whitespace-pre-wrap ${
          isUser 
            ? 'bg-clip-text text-transparent bg-gradient-to-r from-[#FF0080] via-[#7928CA] to-[#0070F3]' 
            : 'text-[#4338CA] drop-shadow-[0_1px_2px_rgba(67,56,202,0.03)]'
        }`}>
          {msg.text}
        </p>

        {!isUser && msg.text && (
          <button 
            onClick={handleCopy}
            className={`absolute -bottom-8 left-6 opacity-0 group-hover:opacity-100 transition-all duration-300 flex items-center gap-2 text-[10px] font-black tracking-[0.3em] uppercase ${copied ? 'text-green-500' : 'text-indigo-600 hover:text-indigo-800'}`}
          >
            <span>{copied ? 'Wisdom Captured' : 'Copy Wisdom'}</span>
            <span className="text-sm">✨</span>
          </button>
        )}

        {isError && onRetry && (
          <button 
            onClick={onRetry}
            className="mt-4 px-6 py-3 bg-gray-900 text-white text-[11px] font-black uppercase tracking-widest rounded-full hover:bg-black transition-all active:scale-95 shadow-lg"
          >
            Reconnect with ELIX ✨
          </button>
        )}
      </div>
    </div>
  );
};

