        </div>
      </div>

      <div className="w-full max-w-2xl mx-auto flex flex-col items-center h-full z-10 px-6 py-8 relative">
        <Header />

        <div className="w-full flex-1 flex flex-col mt-6 sm:mt-12 overflow-hidden">

          {/* STAGE 1: THE BIRTH YEAR ENTRANCE */}
