            <div className="h-full flex flex-col items-center justify-center text-center animate-fade-in space-y-12">
              <div className="space-y-6">
                <h1 className="text-5xl sm:text-7xl font-black tracking-tighter text-gray-900 leading-none">
                  Welcome to <span className="text-indigo-600">ELIX</span>.<br/>
                  <span className="text-2xl sm:text-3xl font-medium text-gray-600 italic">When did your journey begin?</span>
                </h1>
