                  className="w-full max-w-[280px] text-center p-4 bg-transparent border-b-[6px] border-gray-200 focus:border-indigo-500 text-4xl sm:text-5xl font-black text-gray-900 outline-none transition-all duration-700 placeholder:text-gray-200"
                />
