          ) : (

            /* STAGE 2: THE CHAT PAGE */
            <div className="flex-1 flex flex-col overflow-hidden animate-fade-in">
              <div 
                ref={scrollRef}
                className="flex-1 px-2 space-y-16 overflow-y-auto custom-scrollbar scroll-smooth pb-10"
              >
                {history.length === 0 && (
                  <div className="h-full flex flex-col items-center justify-center text-center opacity-60 animate-pulse">
                    <p className="text-gray-800 font-black uppercase tracking-[0.5em] text-[10px]">ELIX is listening. What's on your heart?</p>
                  </div>
                )}
                {history.map((msg, i) => (
                  <MessageBubble key={i} msg={msg} />
                ))}

                {status === Status.LOADING && (
                  <div className="flex justify-start px-6">
                    <div className="flex gap-2">
                       <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce" />
                       <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce [animation-delay:0.2s]" />
                       <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce [animation-delay:0.4s]" />
                    </div>
                  </div>
                )}
              </div>

              {/* INPUT BOX */}
              <div className="mt-6 pb-6 animate-organic-pop">
                <div className="bg-white/70 backdrop-blur-[60px] rounded-[3.5rem] p-3 border border-white/90 shadow-2xl">
                  <ProblemInput 
                    problem={problem}
                    onProblemChange={setProblem}
                    onSubmit={handleSubmit}
                    isLoading={status === Status.LOADING}
                  />
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 0;
          display: none;
        }

        @keyframes organic-pop {
          0% { opacity: 0; transform: scale(0.95) translateY(40px); filter: blur(20px); }
          100% { opacity: 1; transform: scale(1) translateY(0); filter: blur(0); }
        }
        @keyframes fade-in {
          0% { opacity: 0; transform: translateY(40px); filter: blur(20px); }
          100% { opacity: 1; transform: translateY(0); filter: blur(0); }
        }
        @keyframes slow-drift {
          0%, 100% { transform: translate(0, 0) scale(1); }
          50% { transform: translate(8%, 12%) scale(1.1); }
        }
        @keyframes slow-drift-reverse {
          0%, 100% { transform: translate(0, 0) scale(1.1); }
          50% { transform: translate(-10%, -15%) scale(1); }
        }

        .animate-organic-pop {
          animation: organic-pop 1.3s cubic-bezier(0.19, 1, 0.22, 1) forwards;
        }
        .animate-fade-in {
          animation: fade-in 1.8s cubic-bezier(0.19, 1, 0.22, 1) forwards;
        }
        .animate-slow-drift {
          animation: slow-drift 20s ease-in-out infinite;
        }
        .animate-slow-drift-reverse {
          animation: slow-drift-reverse 25s ease-in-out infinite;
        }

        input::-webkit-outer-spin-button,
        input::-webkit-inner-spin-button {
          -webkit-appearance: none;
          margin: 0;
        }
      `}</style>
    </div>
  );
}
